export default "<!doctype html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"utf-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <meta name=\"description\" content=\"MetrAIyux 0S production changelog with Company Knowledge live ingest proof, SkySecure FS27 Vault proof, SkyeVaultOS public-surface proof, Free99/Paid-Apps intake, Marketing Made Easy, SkyeRunners, ConnectLog, Relay13, FS27, SkyeVault/R2 storage proof, Cloudflare deployment evidence, proof receipts, SkyePay, Skyes Reviews, and release history.\">\n  <title>Changelog · MetrAIyux 0S</title>\n  <link rel=\"stylesheet\" href=\"../style.css\">\n  <link rel=\"icon\" type=\"image/png\" href=\"../favicon-32.png\">\n  <style>\n    :root {\n      --changelog-card: rgba(255, 255, 255, .055);\n      --changelog-card-strong: rgba(255, 255, 255, .09);\n      --changelog-line: rgba(243, 212, 131, .34);\n      --changelog-cyan: #35b7ff;\n      --changelog-gold: #f3d483;\n      --changelog-violet: #a88cff;\n    }\n\n    html {\n      overflow-x: hidden;\n    }\n\n    body {\n      background:\n        radial-gradient(circle at 12% 0%, rgba(53, 183, 255, .18), transparent 30%),\n        radial-gradient(circle at 84% 8%, rgba(243, 212, 131, .14), transparent 34%),\n        radial-gradient(circle at 55% 100%, rgba(168, 140, 255, .13), transparent 36%),\n        var(--bg);\n      overflow-x: hidden;\n    }\n\n    .changelog-shell {\n      position: relative;\n      z-index: 2;\n      max-width: 1180px;\n      margin: 0 auto;\n      padding: 36px 22px 86px;\n    }\n\n    .changelog-hero {\n      display: grid;\n      grid-template-columns: minmax(0, 1.2fr) minmax(320px, .8fr);\n      gap: 20px;\n      align-items: stretch;\n      padding: 0 0 30px;\n    }\n\n    .changelog-title {\n      font-size: clamp(36px, 5vw, 60px);\n      line-height: 1.04;\n      margin-bottom: 12px;\n      letter-spacing: 0;\n      color: #f8fbff;\n      text-shadow: 0 0 24px rgba(53, 183, 255, .18), 0 0 30px rgba(243, 212, 131, .12);\n    }\n\n    .changelog-lede {\n      max-width: 780px;\n      color: #d9e4e7;\n      font-size: 18px;\n      line-height: 1.44;\n    }\n\n    .changelog-hero-logo {\n      width: min(390px, 100%);\n      height: auto;\n      max-height: none;\n      object-fit: contain;\n      margin: -18px 0 6px;\n      filter:\n        drop-shadow(0 0 34px rgba(53, 183, 255, .56))\n        drop-shadow(0 0 36px rgba(243, 212, 131, .26));\n    }\n\n    .changelog-hero .hero-actions {\n      margin: 16px 0 0;\n    }\n\n    .changelog-proof-panel,\n    .release-entry {\n      position: relative;\n      overflow: hidden;\n      border: 1px solid rgba(255, 255, 255, .14);\n      border-radius: 8px;\n      background: linear-gradient(180deg, rgba(255, 255, 255, .08), rgba(255, 255, 255, .025));\n      box-shadow: 0 24px 80px rgba(0, 0, 0, .32), 0 0 34px rgba(53, 183, 255, .09);\n    }\n\n    .changelog-proof-panel::before,\n    .release-entry::before {\n      content: \"\";\n      position: absolute;\n      inset: -80% -20%;\n      pointer-events: none;\n      background: linear-gradient(90deg, transparent, rgba(255, 255, 255, .16), transparent);\n      transform: rotate(18deg);\n      animation: changelogSweep 8s ease-in-out infinite;\n    }\n\n    .changelog-proof-panel {\n      padding: 22px;\n      align-self: end;\n    }\n\n    .changelog-proof-panel > * {\n      position: relative;\n      z-index: 1;\n    }\n\n    .proof-grid {\n      display: grid;\n      grid-template-columns: repeat(2, minmax(0, 1fr));\n      gap: 10px;\n      margin-top: 18px;\n    }\n\n    .proof-stat {\n      border: 1px solid rgba(255, 255, 255, .13);\n      border-radius: 8px;\n      background: rgba(0, 0, 0, .22);\n      padding: 14px;\n    }\n\n    .proof-stat strong {\n      display: block;\n      color: #fff;\n      font-size: 30px;\n      line-height: 1;\n    }\n\n    .proof-stat span {\n      display: block;\n      color: var(--muted);\n      font-size: 12px;\n      margin-top: 7px;\n    }\n\n    .release-list {\n      display: grid;\n      gap: 22px;\n      margin-top: 18px;\n    }\n\n    .release-entry {\n      display: grid;\n      grid-template-columns: 190px minmax(0, 1fr);\n      gap: 0;\n      transition: transform .22s ease, border-color .22s ease, box-shadow .22s ease;\n    }\n\n    .release-entry:hover {\n      transform: translateY(-3px);\n      border-color: rgba(53, 183, 255, .55);\n      box-shadow: 0 18px 54px rgba(53, 183, 255, .13), 0 0 28px rgba(243, 212, 131, .14);\n    }\n\n    .release-meta,\n    .release-body {\n      position: relative;\n      z-index: 1;\n      padding: 22px;\n    }\n\n    .release-meta {\n      border-right: 1px solid rgba(255, 255, 255, .1);\n      background: rgba(0, 0, 0, .16);\n    }\n\n    .release-date,\n    .release-version {\n      display: block;\n    }\n\n    .release-date {\n      color: var(--muted);\n      font-size: 13px;\n      margin-bottom: 12px;\n    }\n\n    .release-version {\n      min-width: 54px;\n      min-height: 54px;\n      width: auto;\n      height: auto;\n      display: inline-grid;\n      place-items: center;\n      border-radius: 8px;\n      border: 1px solid var(--changelog-line);\n      color: var(--changelog-gold);\n      font-weight: 900;\n      background: rgba(243, 212, 131, .08);\n      padding: 8px 10px;\n      max-width: 142px;\n      line-height: 1.08;\n      text-align: center;\n      overflow-wrap: anywhere;\n    }\n\n    .release-body h2 {\n      font-size: clamp(24px, 4vw, 36px);\n      margin-bottom: 8px;\n    }\n\n    .release-body p {\n      color: #d9e4e7;\n    }\n\n    .tag-row,\n    .receipt-row {\n      display: flex;\n      flex-wrap: wrap;\n      gap: 8px;\n      margin: 14px 0;\n    }\n\n    .tag-row span,\n    .receipt-row span {\n      border: 1px solid rgba(255, 255, 255, .14);\n      border-radius: 999px;\n      background: rgba(0, 0, 0, .2);\n      color: #d9e4e7;\n      padding: 7px 10px;\n      font-size: 12px;\n      font-weight: 800;\n    }\n\n    .release-points {\n      display: grid;\n      gap: 10px;\n      margin: 18px 0 0;\n      padding: 0;\n      list-style: none;\n    }\n\n    .release-points li {\n      display: grid;\n      grid-template-columns: 12px minmax(0, 1fr);\n      gap: 10px;\n      color: #d9e4e7;\n    }\n\n    .release-points li::before {\n      content: \"\";\n      width: 7px;\n      height: 7px;\n      border-radius: 999px;\n      margin-top: 10px;\n      background: linear-gradient(135deg, var(--changelog-gold), var(--changelog-cyan));\n      box-shadow: 0 0 16px rgba(53, 183, 255, .5);\n    }\n\n    .legacy-note {\n      margin-top: 18px;\n      border-left: 4px solid var(--changelog-gold);\n      padding: 14px 16px;\n      background: rgba(243, 212, 131, .08);\n      color: #e9ddc4;\n    }\n\n    .skyesol-living-field.changelog-field {\n      opacity: .45;\n    }\n\n    @keyframes changelogTextShimmer {\n      from { background-position: 0% center; }\n      to { background-position: 220% center; }\n    }\n\n    @keyframes changelogSweep {\n      0%, 62% { translate: -120% 0; }\n      100% { translate: 120% 0; }\n    }\n\n    @media (max-width: 880px) {\n      .changelog-hero,\n      .release-entry {\n        grid-template-columns: 1fr;\n      }\n\n      .changelog-hero-logo {\n        width: min(340px, 88vw);\n        margin: -8px auto 6px;\n      }\n\n      .release-meta {\n        border-right: 0;\n        border-bottom: 1px solid rgba(255, 255, 255, .1);\n      }\n    }\n\n    @media (max-width: 620px) {\n      .changelog-shell {\n        padding: 24px 16px 72px;\n      }\n\n      .changelog-hero {\n        padding-bottom: 24px;\n      }\n\n      .changelog-hero-logo {\n        width: min(260px, 72vw);\n        margin: -4px auto 6px;\n      }\n\n      .changelog-title {\n        font-size: clamp(34px, 9.3vw, 38px);\n        line-height: 1.04;\n        margin-bottom: 10px;\n      }\n\n      .changelog-lede {\n        font-size: 16px;\n        line-height: 1.38;\n      }\n\n      .changelog-hero .hero-actions {\n        gap: 8px;\n        margin-top: 12px;\n      }\n\n      .changelog-hero .button {\n        padding: 9px 10px;\n        font-size: 12px;\n      }\n\n      .proof-grid {\n        grid-template-columns: 1fr;\n      }\n    }\n\n    @media (prefers-reduced-motion: reduce) {\n      .changelog-title,\n      .changelog-proof-panel::before,\n      .release-entry::before {\n        animation: none !important;\n      }\n    }\n  </style>\n</head>\n<body>\n  <canvas class=\"living-background skyesol-living-field changelog-field\" aria-hidden=\"true\"></canvas>\n  <div class=\"motion-progress scroll-progress motion-chrome\" aria-hidden=\"true\"><i></i></div>\n  <div class=\"motion-cursor-glow pointer-reactive motion-chrome\" aria-hidden=\"true\"></div>\n  <header class=\"site-header\">\n    <a class=\"brand\" href=\"../index.html\"><img class=\"brand-logo floating-logo\" src=\"../assets/metraiyux-0s-emblem-transparent.png\" alt=\"MetrAIyux 0S emblem\"><span class=\"brand-text\">MetrAIyux 0S</span></a>\n    <nav>\n      <a href=\"../index.html\">Home</a>\n      <a href=\"../proof/index.html\">Proof</a>\n      <a href=\"../operator/deployment-ledger.html\">Deployment Ledger</a>\n      <a href=\"../sales/live-proof-router.html\">Live Router</a>\n      <a href=\"../feature-atlas.html\">Feature Atlas</a>\n      <a href=\"../local-brain.html\">Brain</a>\n    </nav>\n  </header>\n  <main class=\"changelog-shell\">\n    <section class=\"changelog-hero\">\n      <div>\n        <p class=\"eyebrow\">Public release record</p>\n        <img class=\"hero-platform-logo changelog-hero-logo floating-logo\" src=\"../assets/metraiyux-0s-logo-transparent.png\" alt=\"MetrAIyux 0S transparent floating logo\">\n        <h1 class=\"changelog-title\">Skye Production Changelog</h1>\n        <p class=\"changelog-lede\">I route the 0S release record through <span class=\"magic-highlighter\" data-highlight=\"highlight\" style=\"--highlighter-color:#87CEFA;display:inline;box-decoration-break:clone;-webkit-box-decoration-break:clone;border-radius:.18em;padding:0 .12em;background:linear-gradient(104deg,transparent .08em,color-mix(in srgb,var(--highlighter-color) 68%,transparent) .08em,color-mix(in srgb,var(--highlighter-color) 68%,transparent) calc(100% - .08em),transparent calc(100% - .08em));text-shadow:0 .08em .22em rgba(0,0,0,.16)\">proof receipts</span>, live Cloudflare surfaces, SkyeVault/R2 storage proof, SkySecure FS27 Vault proof, browser QA, <span class=\"magic-highlighter\" data-highlight=\"underline\" style=\"--highlighter-color:#FF9800;display:inline;box-decoration-break:clone;-webkit-box-decoration-break:clone;text-decoration-line:underline;text-decoration-color:var(--highlighter-color);text-decoration-thickness:.16em;text-underline-offset:.13em;text-decoration-skip-ink:none\">SkyePay</span> handoff evidence, and the legacy release history that used to sit in the old receipt page.</p>\n        <div class=\"hero-actions\">\n          <a class=\"button primary\" href=\"../proof/index.html\">Open Proof Routes</a>\n          <a class=\"button\" href=\"../feature-atlas.html\">Feature Atlas</a>\n          <a class=\"button\" href=\"../Free99/index.html\">Free99 Intake</a>\n          <a class=\"button\" href=\"../operator/deployment-ledger.html\">Deployment Ledger</a>\n          <a class=\"button\" href=\"../proof-vault/skye-secure-fs27-vault-proof.html\">SkySecure Proof</a>\n          <a class=\"button\" href=\"../skye-vault-os/\">SkyeVaultOS</a>\n          <a class=\"button\" href=\"https://merser.pages.dev/\" target=\"_blank\" rel=\"noopener\">Merser</a>\n          <a class=\"button\" href=\"../sales/live-proof-router.html\">Live Proof Router</a>\n        </div>\n      </div>\n      <aside class=\"changelog-proof-panel\" aria-label=\"Current production ledger summary\">\n        <p class=\"eyebrow\">Updated May 22 2026 UTC</p>\n        <h2>Full production in the changelog.</h2>\n        <p>The current production ledger records live surfaces, Cloudflare routes, <span class=\"magic-highlighter\" data-highlight=\"highlight\" style=\"--highlighter-color:#87CEFA;display:inline;box-decoration-break:clone;-webkit-box-decoration-break:clone;border-radius:.18em;padding:0 .12em;background:linear-gradient(104deg,transparent .08em,color-mix(in srgb,var(--highlighter-color) 68%,transparent) .08em,color-mix(in srgb,var(--highlighter-color) 68%,transparent) calc(100% - .08em),transparent calc(100% - .08em));text-shadow:0 .08em .22em rgba(0,0,0,.16)\">browser proof</span> reels, Company Knowledge ingest receipts, SkySecure FS27 Vault proof, and public-safe receipts without exposing private controls.</p>\n        <div class=\"proof-grid\">\n          <div class=\"proof-stat\"><strong>80</strong><span>Verified live surfaces</span></div>\n          <div class=\"proof-stat\"><strong>18</strong><span>Cloudflare Pages projects</span></div>\n          <div class=\"proof-stat\"><strong>17</strong><span>Cloudflare Workers</span></div>\n          <div class=\"proof-stat\"><strong>58</strong><span>Stripe catalog products</span></div>\n          <div class=\"proof-stat\"><strong>27</strong><span>Gate-deployed platform lanes</span></div>\n          <div class=\"proof-stat\"><strong>3/3/9</strong><span>SkySecure packs, grants, events</span></div>\n          <div class=\"proof-stat\"><strong>1,833</strong><span>VaultOS files restored and diffed</span></div>\n          <div class=\"proof-stat\"><strong>18</strong><span>VaultOS commands proved live</span></div>\n          <div class=\"proof-stat\"><strong>20</strong><span>VaultOS public URLs swept live</span></div>\n        </div>\n      </aside>\n    </section>\n\n    <section aria-label=\"Release timeline\">\n      <p class=\"eyebrow\">Timeline</p>\n      <div class=\"release-list\">\n        <article class=\"release-entry\" id=\"devs-playbook-marketing-keys\">\n          <div class=\"release-meta\">\n            <time class=\"release-date\" datetime=\"2026-05-22\">May 22, 2026</time>\n            <span class=\"release-version\">Devs Playbook</span>\n          </div>\n          <div class=\"release-body\">\n            <div class=\"tag-row\"><span>Marketing Keys</span><span>skdevpbk</span><span>Email gate</span><span>Developer Playbook</span><span>Deep smoke only</span><span>Live proof required</span></div>\n            <h2>The 0S Devs Playbook now has a marketing-key email gate and source-level workflow map.</h2>\n            <p>A standalone <code>/devs-playbook/</code> page was added for the operator/developer workflow map: credential names, gate lanes, Free99 demo flow, SkyeVault/MyDrive commands, MCP mining, deploy commands, proof policy, and handoff locations. The page intentionally lists key names and custody paths only; it does not render raw secret values.</p>\n            <ul class=\"release-points\">\n              <li>The new email gate stores signups in the <code>marketing_keys</code> ledger under campaign tag <code>skdevpbk</code>, with tracked users shaped like <code>emailname-skdevpbk</code>.</li>\n              <li>The marketing-key session cookie is scoped to the playbook surface and does not unlock the broader 0S, owner routes, Sign In Pro, or admin surfaces.</li>\n              <li>Owner analytics are available at <code>/api/marketing-keys/signups?key=skdevpbk</code> after shared 0S owner auth.</li>\n              <li>Local deep smoke was added at <code>metraiyux_0s_site/tests/marketing-keys-dev-playbook-flow.mjs</code> and writes <code>test-artifacts/marketing-keys-dev-playbook/smoke-report.json</code>.</li>\n              <li>This entry is not a live readiness claim. Deploy and headed desktop/mobile browser proof are still required before presenting the live playbook link as ready.</li>\n            </ul>\n            <div class=\"receipt-row\"><span><code>metraiyux_0s_site/devs-playbook/index.html</code></span><span><code>metraiyux_0s_site/devs-playbook/login.html</code></span><span><code>metraiyux_0s_site/cloudflare/worker.js</code></span><span><code>.vscode/Handoffs/2026-05-22-devs-playbook-marketing-keys-handoff.md</code></span></div>\n          </div>\n        </article>\n\n        <article class=\"release-entry\" id=\"skyesol-company-knowledge-ingest\">\n          <div class=\"release-meta\">\n            <time class=\"release-date\" datetime=\"2026-05-22\">May 22, 2026</time>\n            <span class=\"release-version\">SkyeSol Knowledge</span>\n          </div>\n          <div class=\"release-body\">\n            <div class=\"tag-row\"><span>Company Knowledge</span><span>SkyeSol</span><span>Skyes Over London</span><span>0S Brain</span><span>Shared FS27 gate</span><span>Live API proof</span><span>Headed browser proof</span></div>\n            <h2>SkyeSol and Skyes Over London company memory is now in the live 0S knowledge base.</h2>\n            <p>The SkyeSol archive was unpacked, deep scanned, written into longform company dossiers, synced into the local 0S brain, and ingested into the live <code>metraiyux-0s</code> Company Knowledge platform base through the shared owner gate.</p>\n            <ul class=\"release-points\">\n              <li>The archive source <code>Zenith/skyesol-main.zip</code> was extracted and scanned across 1,575 files, including 1,075 HTML/Markdown pages and about 2.5M word-like tokens.</li>\n              <li>Two durable brain notes were created: <code>Skyes Over London LC Company Dossier</code> and <code>Skyes Over London Deep Scan Knowledge Pack - 2026-05-21</code>.</li>\n              <li>The local Obsidian sync now includes both notes with 141 combined chunks, and the private/public neural maps were regenerated with the new deep-scan node present.</li>\n              <li>The live Company Knowledge API upserted item IDs <code>skyes-over-london-lc-company-dossier-2026-05-21</code> and <code>skyes-over-london-deep-scan-knowledge-pack-2026-05-21</code> into base <code>metraiyux-0s</code>.</li>\n              <li>The live context query for <code>kAIxU Gateway13 Lane Vault SkyeFyve SkyeSuite SkyeSol company doctrine</code> returned the new company knowledge items.</li>\n              <li>Headed Chromium proof opened the deployed owner console, loaded bases/items, built the SkyeSol context pack, scrolled desktop and mobile, and recorded zero console errors and zero failed network requests.</li>\n              <li>No app-specific founder/admin/client password was created; the ingest used the existing shared 0S/FS27/SkyGate/Free99 owner session through <code>/api/owner/admin-login</code>.</li>\n            </ul>\n            <div class=\"receipt-row\"><span><code>Zenith/SKYESOL_COMPANY_DOSSIER.md</code></span><span><code>obsidian-vault/00-command-center/Skyes Over London Deep Scan Knowledge Pack - 2026-05-21.md</code></span><span><code>test-artifacts/company-knowledge-skyesol-ingest/2026-05-22T05-19-07-935Z-live-ingest-receipt.json</code></span><span><code>test-artifacts/company-knowledge-skyesol-ingest/2026-05-22T06-00-44-011Z-combined-live-browser-proof.json</code></span><span><code>.vscode/Handoffs/2026-05-22-skyesol-company-knowledge-deep-scan-handoff.md</code></span></div>\n          </div>\n        </article>\n\n        <article class=\"release-entry\" id=\"legal-skyes-ai-operators-notice\">\n          <div class=\"release-meta\">\n            <time class=\"release-date\" datetime=\"2026-05-22\">May 22, 2026</time>\n            <span class=\"release-version\">Legal Skyes AI Operators</span>\n          </div>\n          <div class=\"release-body\">\n            <div class=\"tag-row\"><span>Legal Skyes</span><span>AI operators</span><span>kAIxu 6.7</span><span>Cloudflare Pages</span><span>Live browser proof</span></div>\n            <h2>Legal Skyes now has the AI Operators disclosure and kAIxu authority notice live.</h2>\n            <p>The AI Operators handoff was moved out of <code>.vscode/Handoffs/AI-Operators-legal.html</code> and into the Legal Skyes website as a dedicated public legal page at <code>/legal/ai-operators/</code>. The page explains kAIxu 6.7 and related AI operators, authority limits, no-professional-advice language, human review requirements, privacy and AI data use, Arizona breach/consumer-protection posture, incident reporting, and the public wording for AI chat footers.</p>\n            <ul class=\"release-points\">\n              <li>The page is linked from the Legal Skyes home, Legal Hub, public legal brain copy, and short routes <code>/ai-operators</code>, <code>/kaixu</code>, and <code>/kai-xu</code>.</li>\n              <li>The canonical live Legal Skyes domain is <code>https://skyes-over-london-legal.pages.dev/</code>; <code>solenterprises.org</code> currently serves a separate gateway and was not claimed as the ready legal URL.</li>\n              <li>The fresh Cloudflare Pages deployment is <code>946d9ac8-4543-4d51-a577-02508e788705</code>, with preview <code>https://946d9ac8.skyes-over-london-legal.pages.dev</code>.</li>\n              <li>Headed production proof passed desktop and mobile browser operation: 102 actions per viewport, all short routes returned HTTP <code>200</code>, Legal Hub/Home navigation opened the AI Operators page, all table-of-contents anchors changed state, 66 scroll-stop screenshots were captured, and no unresolved console, page, HTTP, media, or network failures remained.</li>\n            </ul>\n            <div class=\"receipt-row\"><span><a href=\"https://skyes-over-london-legal.pages.dev/legal/ai-operators/\" target=\"_blank\" rel=\"noopener\">AI Operators notice</a></span><span><a href=\"https://skyes-over-london-legal.pages.dev/ai-operators\" target=\"_blank\" rel=\"noopener\">Short link</a></span><span><code>legalskyes-website/legal/ai-operators/index.html</code></span><span><code>test-artifacts/live-browser-verifier/2026-05-22T05-48-23-969Z-legal-skyes-ai-operators/live-browser-verification-report-normalized-pass.json</code></span></div>\n          </div>\n        </article>\n\n        <article class=\"release-entry\" id=\"merser-mcp-skyes-over-london-client-access\">\n          <div class=\"release-meta\">\n            <time class=\"release-date\" datetime=\"2026-05-21\">May 21, 2026</time>\n            <span class=\"release-version\">Merser 1.0.1</span>\n          </div>\n          <div class=\"release-body\">\n            <div class=\"tag-row\"><span>Merser</span><span>Skyes Over London</span><span>npx CLI</span><span>stdio MCP</span><span>Cloudflare Pages</span><span>Stress receipt</span><span>Live browser proof</span></div>\n            <h2>Merser by Skyes Over London is now the named source-world developer lane.</h2>\n            <p>The MCP4 source-world work is now branded as Merser by Skyes Over London, with the actual Skyes Over London logo, a PWA manifest, a real npm package, executable bins, repeatable stress testing, and a canonical public URL at <code>https://merser.pages.dev/</code>.</p>\n            <ul class=\"release-points\">\n              <li>The published npm package <code>@skyes0verl0nd0n/merser</code> exposes real executable aliases: <code>Merser</code>, <code>merser</code>, and <code>merser-mcp</code>, all pointing at the shebang stdio server.</li>\n              <li>The dev handoff includes local stdio, local HTTP, Cloudflare Streamable HTTP, gate-owned auth, MCP client config, build/deploy commands, and <code>npm run stress</code>.</li>\n              <li>The public site uses the existing Skyes Over London logo as the site mark and PWA icon instead of a generated placeholder.</li>\n              <li>The 0S home and 0s SkyeWay now expose Merser as a real public developer lane while preserving the shared FS27/SkyGate/Free99 gate boundary for remote MCP access.</li>\n              <li>The valuation update treats the reported $6K access interest as pipeline validation only until it is paid or converted to retained revenue.</li>\n            </ul>\n            <div class=\"receipt-row\"><span><a href=\"https://merser.pages.dev/\" target=\"_blank\" rel=\"noopener\">Merser</a></span><span><a href=\"https://www.npmjs.com/package/@skyes0verl0nd0n/merser\" target=\"_blank\" rel=\"noopener\">npm package</a></span><span><a href=\"https://merser.pages.dev/health\" target=\"_blank\" rel=\"noopener\">Health</a></span><span><code>.vscode/MCP4/tools/stress-merser.mjs</code></span><span><code>.vscode/MCP4/REMOTE_ACCESS.md</code></span><span>Shared 0S gate</span></div>\n          </div>\n        </article>\n\n        <article class=\"release-entry\" id=\"sovereigndocs-docxmax-lean-lane\">\n          <div class=\"release-meta\">\n            <time class=\"release-date\" datetime=\"2026-05-21\">May 21, 2026</time>\n            <span class=\"release-version\">SovereignDocs SkyeDocxMax Lean Lane</span>\n          </div>\n          <div class=\"release-body\">\n            <div class=\"tag-row\"><span>SovereignDocs</span><span>SkyeDocxMax</span><span>Cloudflare Pages</span><span>FS27 gate</span><span>No per-app auth</span><span>Live browser proof</span></div>\n            <h2>SovereignDocs docs now have their own lean deployment without splitting the user runtime.</h2>\n            <p>The SkyeDocxMax docs/editor slice is now deployed as a small gate-owned Pages origin, while the usable route stays inside the main 0S at <code>/Free99/apps/sovereigndocs/skye-docx-max/</code>. Deployment logistics are separate; auth and user flow remain owned by the 0S.</p>\n            <ul class=\"release-points\">\n              <li>The new <code>sovereigndocs-docxmax-lane</code> Pages project deploys only the docs/editor slice and shared SovereignDocs assets: 84 files, about 6.7 MB, under Cloudflare Pages' 20,000-file cap.</li>\n              <li>The direct origin redirects browser document requests to the main 0S owner login with a return path, returns <code>401</code> for direct non-HTML access, and serves assets only to the main Worker through a private origin header.</li>\n              <li>The main 0S Worker now proxies only <code>/Free99/apps/sovereigndocs/skye-docx-max/</code> to that lean origin after <code>enforceZeroOsGate</code>; no app-specific admin/login layer was added.</li>\n              <li>The Free99 owner code aliases were re-synced on the live Worker so the owner admin code unlocks the 0S gate as intended.</li>\n              <li>Headed production proof passed direct-origin gate checks, desktop owner unlock, mobile owner unlock, same-domain route forwarding, no per-app gate overlay, and no app-specific gate session keys.</li>\n            </ul>\n            <div class=\"receipt-row\"><span><a href=\"../Free99/apps/sovereigndocs/skye-docx-max/\">SovereignDocs SkyeDocxMax</a></span><span><code>https://sovereigndocs-docxmax-lane.pages.dev</code></span><span><code>1e332551-eb7a-4f35-9762-0e1d69782ce6</code></span><span><code>test-artifacts/sovereigndocs-docxmax-lean-live/latest-live-browser-report.json</code></span><span><code>test-artifacts/sovereigndocs-docxmax-lane/build-manifest.json</code></span></div>\n          </div>\n        </article>\n\n        <article class=\"release-entry\" id=\"skyevaultpro-docxmax-local-bridge\">\n          <div class=\"release-meta\">\n            <time class=\"release-date\" datetime=\"2026-05-21\">May 21, 2026</time>\n            <span class=\"release-version\">SkyeVault Pro Bridge</span>\n          </div>\n          <div class=\"release-body\">\n            <div class=\"tag-row\"><span>SkyeVault Pro</span><span>SkyeDocxMax</span><span>FS27 gate</span><span>Local vault</span><span>Suite events</span><span>Paid backup add-on</span></div>\n            <h2>SkyeVault Pro now talks to the current SkyeDocxMax through the shared 0S gate.</h2>\n            <p>SkyeVault Pro stays local-first, but it is no longer carrying a second bundled doc editor. The live vault opens the current same-domain SkyeDocxMax, pushes edits back into the local IndexedDB vault, stages dev-drive imports locally, and keeps hosted backup behind an explicit $4.99/mo add-on.</p>\n            <ul class=\"release-points\">\n              <li>SkyeVault Pro now opens <code>/Marketing-Made-Easy/SkyeDocxMax/editor.html</code> with <code>vaultDocId</code>, <code>source=skyevaultpro</code>, and a vault return path.</li>\n              <li>The old SkyeVault Pro <code>apps/docx</code> runtime was deleted from the live SkyeVault Pro app tree; its useful bridge logic was lifted into <code>assets/js/skye-docxmax-vault-bridge.js</code>, and legacy URLs redirect to the current editor after the shared gate.</li>\n              <li>The shared Free99 route helper now allows cross-app 0S roots so mounted apps can link to SkyeDocxMax, WebCreator, Client App Factory, and other 0S lanes without being rewritten into their own app folder.</li>\n              <li>The new <code>vault:pro:stage</code>, <code>vault:pro:from-dev</code>, and <code>vault:pro:stage:latest</code> commands create local SkyeVault Pro import folders from sanitized dev-drive material and are stress-backed in <code>test-artifacts/skyevaultpro-backed-claims/latest-proof.json</code>.</li>\n              <li>Hosted customer vault backup is off by default; the Netlify backup function default-denies unless the Sovereign Backup add-on is enabled.</li>\n              <li>The 0S Worker now exposes gate-owned <code>/api/suite-events</code> so SkyeDocxMax and future apps can begin using the shared app-event layer instead of disconnected local assumptions; live proof posts and reads back a suite event behind the shared session.</li>\n            </ul>\n            <div class=\"receipt-row\"><span><a href=\"../Free99/apps/skyevaultpro/drive/\">SkyeVault Pro drive</a></span><span><a href=\"../Marketing-Made-Easy/SkyeDocxMax/editor.html\">SkyeDocxMax</a></span><span><code>test-artifacts/skyevaultpro-docxmax-live/latest-live-browser-report.json</code></span><span><code>test-artifacts/skyevaultpro-backed-claims/latest-proof.json</code></span><span>No per-app auth</span><span>Local backup default</span></div>\n          </div>\n        </article>\n\n        <article class=\"release-entry\" id=\"gray-skyes-portfolio-cleanup-final-push\">\n          <div class=\"release-meta\">\n            <time class=\"release-date\" datetime=\"2026-05-20\">May 20, 2026</time>\n            <span class=\"release-version\">Gray Skyes Cleanup</span>\n          </div>\n          <div class=\"release-body\">\n            <div class=\"tag-row\"><span>Gray Skyes</span><span>Portfolio</span><span>SkyeKnowlogy</span><span>Duplicate cleanup</span><span>Live browser proof</span></div>\n            <h2>The portfolio stays live, and the retired Gray Skyes duplicate surface is no longer served.</h2>\n            <p>The canonical Gray Skyes portfolio was rebuilt as the clean public entrypoint for the 0S operating-stack work, while duplicate marketing routes that carried the old screenshot-style surface were retired from public service.</p>\n            <ul class=\"release-points\">\n              <li>The canonical portfolio remains live at <a href=\"https://gray-skyes-founder-portfolio.pages.dev/\">gray-skyes-founder-portfolio.pages.dev</a> with the `/` portfolio route and `/skyeknowlogy` build-standard route.</li>\n              <li>The portfolio bundle no longer includes the old cinematic copy, screenshot-style shell, living-background import, or duplicate public experiment surface.</li>\n              <li>The canonical marketing project was redeployed as `pages:5296d66f` and the legacy compatibility mirror was redeployed as `pages:19967783` so retired Gray Skyes and founder-portfolio paths no longer show the bad page.</li>\n              <li>Exact retired marketing paths now return only not-found/download content, and `.html` plus mirror routes return hard 404 responses.</li>\n              <li>The canonical portfolio was redeployed as `pages:8739d85e` with desktop and mobile interaction proof across Portfolio and SkyeKnowlogy navigation.</li>\n              <li>Headed live browser proof checked canonical portfolio routes, canonical retired marketing routes, and legacy mirror retired routes with zero banned old-surface text.</li>\n            </ul>\n            <div class=\"receipt-row\"><span><a href=\"https://gray-skyes-founder-portfolio.pages.dev/\">Portfolio</a></span><span><a href=\"https://gray-skyes-founder-portfolio.pages.dev/skyeknowlogy\">SkyeKnowlogy</a></span><span><code>pages:8739d85e</code></span><span><code>pages:5296d66f</code></span><span><code>pages:19967783</code></span><span><code>test-artifacts/live-browser-verifier/2026-05-20T22-27-26-555Z-gray-skyes-portfolio-production-final-push-clean/live-browser-verification-report.json</code></span></div>\n          </div>\n        </article>\n\n        <article class=\"release-entry\" id=\"founder-command-relay13-live-command\">\n          <div class=\"release-meta\">\n            <time class=\"release-date\" datetime=\"2026-05-20\">May 20, 2026</time>\n            <span class=\"release-version\">Founder Relay13 Command</span>\n          </div>\n          <div class=\"release-body\">\n            <div class=\"tag-row\"><span>Founder Command</span><span>Relay13</span><span>FS27 gate</span><span>Mobile command</span><span>Operator inbox</span></div>\n            <h2>Founder Command now runs a real Relay13 operator lane from the phone.</h2>\n            <p>The Founder Command surface is no longer allowed to talk like it queued phantom work. It now creates live Relay13 conversations only when the 0S Worker action succeeds, keeps the command lane behind the shared FS27/Free99 session, and gives the founder a mobile inbox for real operator replies.</p>\n            <ul class=\"release-points\">\n              <li>The Founder Command Inbox tab creates Relay13 conversations, loads the live admin inbox, opens selected threads, and sends operator/system replies from the mounted 0S surface.</li>\n              <li>The chat command route creates a live Relay13 conversation only when the Worker completes the action; status questions return factual system state instead of fake operator-review receipt language.</li>\n              <li>Relay13 now accepts the additional 0S-owned admin secret name <code>RELAY13_PLATFORM_ADMIN_TOKEN</code>, while the existing platform token stays unrotated.</li>\n              <li>The Inbox UI preserves success messages after refresh so a real send does not vanish into confusing empty state.</li>\n              <li>The 0S Worker deployed as version <code>903bd704-0064-467e-9933-e824a3c93ddb</code>, and Relay13 Core deployed as version <code>bdffd7be-e2a6-400f-b874-98231539720f</code>.</li>\n              <li>Production API proof passed owner login, live Relay13 admin inbox, conversation creation, readback, operator reply, and chat-triggered live conversation creation.</li>\n              <li>Headed browser proof passed desktop/mobile shared-gate login, live Relay13 inbox load, selected-thread operator replies, factual command chat, old fake language absent, zero material console errors, and zero material failed network requests.</li>\n            </ul>\n            <div class=\"receipt-row\"><span><a href=\"../founder-command/?tab=inbox\">Founder Command inbox</a></span><span><a href=\"../api/founder-command/inbox\">Inbox API</a></span><span><code>test-artifacts/founder-command-relay13-live/2026-05-20T21-01-49-328Z-api-proof.json</code></span><span><code>test-artifacts/live-browser-verifier/2026-05-20T21-22-46-726Z-founder-command-relay13-live-clean/live-browser-verification-report.json</code></span><span>Shared FS27/Free99 gate</span><span>No app-specific auth lane</span></div>\n          </div>\n        </article>\n\n        <article class=\"release-entry\" id=\"skyeway-fs27-gate-atlas\">\n          <div class=\"release-meta\">\n            <time class=\"release-date\" datetime=\"2026-05-20\">May 20, 2026</time>\n            <span class=\"release-version\">SkyeWay Gate Atlas</span>\n          </div>\n          <div class=\"release-body\">\n            <div class=\"tag-row\"><span>SkyeWay</span><span>FS27 gate</span><span>Client App Factory</span><span>Free99</span><span>Route Atlas</span></div>\n            <h2>SkyeWay now maps mounted 0S routes and keeps client apps behind FS27.</h2>\n            <p>The Skyeway route atlas was rebuilt around the real mounted 0S surface map so operators can move through the system without dragging source mirrors, generated template bulk, or app-local auth assumptions into the live view.</p>\n            <ul class=\"release-points\">\n              <li>The generated atlas now covers 2,548 mounted/operator routes and labels the 167 Client App Factory app routes as <code>fs27-owner-gated-client-app</code>.</li>\n              <li>Source mirrors, generated SovereignDocs template bulk, Cloudflare build output, tests, proof folders, and private/server folders are excluded from the navigable Skyeway payload.</li>\n              <li>The live Skyeway UI now shows gate-policy labels, a Client Apps category, and the FS27 gate authority count so the map explains what is actually protected.</li>\n              <li>The main Worker no longer public-bypasses <code>/client-app-factory/client-apps/*</code>; mounted client apps now fall through the shared 0S FS27/Free99 gate perimeter.</li>\n              <li>The audit receipt records the manifest count, client-app policy check, source-mirror exclusion check, and Worker syntax proof.</li>\n            </ul>\n            <div class=\"receipt-row\"><span><a href=\"../skyeway.html\">Skyeway</a></span><span><a href=\"../client-app-factory/\">Client App Factory</a></span><span><a href=\"../admin/login.html\">FS27 owner gate</a></span><span><code>metraiyux_0s_site/audits/SKYEWAY_FS27_GATE_AUDIT_2026-05-20.md</code></span><span><code>assets/skyeway-routes.js</code></span><span>No source mirrors in atlas</span></div>\n          </div>\n        </article>\n        <article class=\"release-entry\" id=\"still2vid-free99-app-interconnect\">\n          <div class=\"release-meta\">\n            <time class=\"release-date\" datetime=\"2026-05-20\">May 20, 2026</time>\n            <span class=\"release-version\">Still2Vid Free99</span>\n          </div>\n          <div class=\"release-body\">\n            <div class=\"tag-row\"><span>Free99</span><span>FS27 gate</span><span>Client App Factory</span><span>SkyeWebCreatorMax</span><span>Media handoff</span></div>\n            <h2>Still2Vid Forge v4 is now a gated 0S app connected to the creation stack.</h2>\n            <p>The image-to-video forge moved from a ZIP into the 0S Free99 app lane, with source-authority checks, browser-local handoff from Client App Factory and SkyeWebCreatorMax, and final headed proof on Worker version <code>24217541-2cea-484a-a6e6-230be4104f90</code>.</p>\n            <ul class=\"release-points\">\n              <li><code>/Free99/apps/still2vid-forge/</code> now mounts the app with the shared Free99 gate script and <code>platform_id=still2vid-forge</code>.</li>\n              <li>Client App Factory can pass uploaded, harvested, licensed, or AI-receipted media through <code>METRAIYUX_MEDIA_HANDOFF</code>.</li>\n              <li>The factory no longer treats fake initials/text marks as acceptable client identity fallback.</li>\n              <li>SkyeWebCreatorMax has a Media Forge handoff path so generated site work can move into motion/logo-video production.</li>\n              <li>Internal docs now define the next app-event bus layer for connected 0S automation.</li>\n              <li>Final headed production proof verified desktop and mobile owner login, Still2Vid upload/play/export, Client App Factory handoff, SkyeWebCreatorMax handoff, Free99 hub copy, gated proof receipt copy, and changelog copy with zero console errors, failed requests, or HTTP errors.</li>\n            </ul>\n            <div class=\"receipt-row\"><span>Free99 route</span><span>Gate owned</span><span>No fake logo fallback</span><span>App interconnect</span><span><code>24217541</code></span><span><code>test-artifacts/live-browser-verifier/2026-05-20T20-41-40-272Z-still2vid-free99-production/live-browser-verification-report.json</code></span></div>\n          </div>\n        </article>\n        <article class=\"release-entry\" id=\"citadeldb-sovereign-direct-links\">\n          <div class=\"release-meta\">\n            <time class=\"release-date\" datetime=\"2026-05-20\">May 20, 2026</time>\n            <span class=\"release-version\">CitadelDB Sovereign Links</span>\n          </div>\n          <div class=\"release-body\">\n            <div class=\"tag-row\"><span>CitadelDB</span><span>Tenant export</span><span>Root env</span><span>Live browser proof</span><span>Gate-owned data</span></div>\n            <h2>I made the database lane direct-linkable and tied client records to sovereign export routes.</h2>\n            <p>The CitadelDB dashboard now shows direct links for the live dashboard, safe public health, canonical tenant map, gated tenant exports, mirror ledger, status, catch-up queue, and NorthStar mount. The root <code>.env</code> now carries those public route variables so the links are not trapped in chat.</p>\n            <ul class=\"release-points\">\n              <li>Tenant leads now write the tenant record, tenant event, and Citadel mirror/catch-up receipt automatically instead of only saying the database needs a write.</li>\n              <li>I added <code>/api/0s/tenant-export</code> and <code>/api/0s/sovereign-export</code> for Gate-authenticated JSON exports by <code>clientId</code>.</li>\n              <li>The Citadel dashboard now includes a direct-link panel for dashboard, health, tenant map, Empire Pallets export, 480 Realty export, status, ledger, catch-up queue, and NorthStar.</li>\n              <li>The live browser verifier now auto-runs headed Chromium under Xvfb when the environment has no display; screenshot-only and headless-only proof still do not count.</li>\n              <li>Private test/source paths are blocked before static asset serving, including <code>/tests/</code>.</li>\n              <li>Focused live browser proof clicked the direct health and tenant-map links on desktop and mobile with zero console errors and zero failed requests; the exact current Worker version is tracked in the root <code>.env</code>.</li>\n            </ul>\n            <div class=\"receipt-row\"><span><a href=\"../citadeldb/\">CitadelDB dashboard</a></span><span><a href=\"../api/citadel/health\">Citadel health</a></span><span><a href=\"../api/0s/tenant-map\">Tenant map</a></span><span><a href=\"../api/0s/tenant-export?clientId=empire-pallets\">Empire export</a></span><span><a href=\"../api/0s/tenant-export?clientId=480-realty-property-management\">480 export</a></span><span><code>test-artifacts/live-browser-verifier/2026-05-20T15-26-01-202Z-citadeldb-direct-links-final-v2/live-browser-verification-report.json</code></span><span><code>test-artifacts/live-browser-verifier/2026-05-20T15-27-32-600Z-citadeldb-direct-links-human-clicks-final/live-direct-link-click-report.json</code></span></div>\n          </div>\n        </article>\n\n        <article class=\"release-entry\" id=\"tenant-backbone-relay-content-engine\">\n          <div class=\"release-meta\">\n            <time class=\"release-date\" datetime=\"2026-05-20\">May 20, 2026</time>\n            <span class=\"release-version\">0S Tenant Backbone</span>\n          </div>\n          <div class=\"release-body\">\n            <div class=\"tag-row\"><span>Client App Factory</span><span>Valley Verified</span><span>Relay13</span><span>ConnectLog</span><span>SkyeDocxMax</span><span>Content Engine</span><span>SkyePay AI tiers</span><span>Gate-owned SignIn Pro</span></div>\n            <h2>I added one tenant spine tying client apps, Valley profiles, inboxes, docs, media, and AI usage together.</h2>\n            <p>The 0S Worker now exposes a canonical tenant map that ties <code>clientId</code>, <code>workspaceId</code>, <code>valleyBusinessId</code>, <code>relayInboxId</code>, and install QR. Client App Factory intake now records tenant leads into the same backbone and attempts Relay13/ConnectLog delivery for the matching tenant inbox.</p>\n            <ul class=\"release-points\">\n              <li>I added <code>/api/0s/tenant-map</code>, <code>/api/0s/tenant-leads</code>, <code>/api/0s/tenant-inbox</code>, AI tier policy endpoints, SkyeDocxMax share persistence, and media reuse package routes.</li>\n              <li>I wired Client App Factory intake into the tenant lead ledger so public app submissions carry the right workspace, Valley profile, Relay13 inbox, install QR, and local-brain-first AI policy.</li>\n              <li>I added Content Engine import routes for Marketing Made Easy and SkyeMediaCenter packages, with dispatch still approval-gated and <code>provider_call_made:false</code> unless a paid tier and connector policy allow it.</li>\n              <li>I corrected NorthStar SignInPro language across the mounted app and audits: it is a mounted app inside the 0S, and the 0S Gate owns identity/session authority.</li>\n              <li>Local proof passed 35 Worker tests across tenant backbone, Relay13/ConnectLog, SkyeMediaCenter, API routing, security gates, Marketing Made Easy, and SovereignDocs.</li>\n            </ul>\n            <div class=\"receipt-row\"><span><a href=\"../api/0s/tenant-map\">Tenant map API</a></span><span><a href=\"../api/0s/ai-response-tiers\">AI tier policy</a></span><span><code>metraiyux_0s_site/tests/tenant-backbone-integration.test.mjs</code></span><span><code>test-artifacts/0s-tenant-backbone/live-proof-2026-05-20.json</code></span><span>Gate auth preserved</span></div>\n          </div>\n        </article>\n\n        <article class=\"release-entry\" id=\"northstar-login-redesign-fade-board-actions\">\n          <div class=\"release-meta\">\n            <time class=\"release-date\" datetime=\"2026-05-20\">May 20, 2026</time>\n            <span class=\"release-version\">NorthStar Login Redesign</span>\n          </div>\n          <div class=\"release-body\">\n            <div class=\"tag-row\"><span>NorthStar</span><span>SignIn Pro</span><span>Fade Masters</span><span>MCP validated</span><span>Live proof</span></div>\n            <h2>I rebuilt the NorthStar workspace login and made the Fade Masters board controls real.</h2>\n            <p>The Fade Masters top-right board no longer shows fake-looking <code>Book</code>, <code>Queue</code>, and <code>Receipt</code> labels. They are real controls now. The NorthStar workspace login has been redesigned as a clean workspace gateway with one primary NorthStar logo and a restrained Skyes Over London backing seal.</p>\n            <ul class=\"release-points\">\n              <li>I changed the Fade Masters booking-board labels into clickable anchors wired to <code>#book</code>, <code>#queue</code>, and <code>#receipt</code>.</li>\n              <li>I replaced the old NorthStar login composition with a two-panel workspace gateway, preserved workspace login, preserved 0S owner unlock, and kept the About SignIn Pro tab.</li>\n              <li>I removed the awkward side-by-side deity logo treatment and moved the Skyes Over London deity mark into a backing seal so it supports NorthStar instead of competing with it.</li>\n              <li>I reran the repo MCP workflow for both surfaces; the NorthStar validation now passes, including the letter-spacing audit.</li>\n            </ul>\n            <div class=\"receipt-row\"><span><a href=\"../client-app-factory/client-apps/fade-masters-phx/\">Fade Masters app</a></span><span><a href=\"../northstar/?workspace=fade-masters-phx&amp;client=fade-masters-phx\">NorthStar workspace login</a></span><span><code>test-artifacts/northstar-login-redesign-fade-board-2026-05-20/local-proof-report.json</code></span><span><code>test-artifacts/northstar-login-redesign-fade-board-2026-05-20/live-proof-report.json</code></span><span><code>test-artifacts/direct-mcp/northstar-mcp-tooling-receipt.json</code></span></div>\n          </div>\n        </article>\n\n        <article class=\"release-entry\" id=\"northstar-intro-bobs-video-preview\">\n          <div class=\"release-meta\">\n            <time class=\"release-date\" datetime=\"2026-05-20\">May 20, 2026</time>\n            <span class=\"release-version\">SignIn Pro Intro + Bob Video</span>\n          </div>\n          <div class=\"release-body\">\n            <div class=\"tag-row\"><span>NorthStar</span><span>SignIn Pro</span><span>Bob's Smoke Shop</span><span>Video proof</span><span>Browser QA</span></div>\n            <h2>I added the quick SignIn Pro intro and replaced Bob's preview placeholder with the real app-build video.</h2>\n            <p>NorthStar now shows a short welcome layer before the workspace appears, then exits quickly into the app. The SignIn Pro logo is contained in its own stage so it no longer sits over login copy, proof cards, or the workspace access panel.</p>\n            <ul class=\"release-points\">\n              <li>I added a quick NorthStar SignIn Pro intro that thanks the user and keeps the app hidden until the intro finishes.</li>\n              <li>I resized and contained the SignIn Pro logo stage on desktop and mobile so the brand mark does not cover the page content.</li>\n              <li>I added Bob's Smoke Shop as a built-in NorthStar workspace profile so his SignIn Pro preview can show the real <code>bobs-live-build.mp4</code> video instead of the generic fallback.</li>\n              <li>I added the same real Bob app-build video to <code>client-preview/bobs-smoke-shop.html</code> so the private preview room is not a text-only or poster-only page.</li>\n              <li>Local and live Playwright proof passed desktop and mobile intro behavior, logo non-overlap, MP4 resolution, no horizontal overflow, and no browser errors.</li>\n            </ul>\n            <div class=\"receipt-row\"><span><a href=\"../northstar/?workspace=bobs-smoke-shop\">Bob SignIn Pro workspace</a></span><span><a href=\"../client-preview/bobs-smoke-shop.html\">Bob client preview</a></span><span><code>test-artifacts/northstar-intro-bobs-video-2026-05-20/local-playwright-report.json</code></span><span><code>test-artifacts/northstar-intro-bobs-video-2026-05-20/live-playwright-report.json</code></span><span><code>bobs-live-build.mp4</code></span><span>Service worker cache bumped</span></div>\n          </div>\n        </article>\n\n        <article class=\"release-entry\" id=\"sovereigndocs-skye-docxmax-persistence\">\n          <div class=\"release-meta\">\n            <time class=\"release-date\" datetime=\"2026-05-20\">May 20, 2026</time>\n            <span class=\"release-version\">SovereignDocs x SkyeDocxMax Persistence</span>\n          </div>\n          <div class=\"release-body\">\n            <div class=\"tag-row\"><span>SovereignDocs</span><span>SkyeDocxMax</span><span>Vault records</span><span>Content Engine</span><span>FS27 auth</span><span>Live write proof</span></div>\n            <h2>I wired SkyeDocxMax returns back into SovereignDocs and the 0S Content Engine.</h2>\n            <p>SovereignDocs now creates real SkyeDocxMax handoff sessions, accepts edited returns, and stores those returns as documents plus vault records behind the shared FS27/SkyGate lane. The Content Engine can package approved work into local-brain chunks and repo tasks while keeping external provider dispatch blocked until operator approval and connector configuration exist.</p>\n            <ul class=\"release-points\">\n              <li>I added live 0S routes for SkyeDocxMax sessions, returns, document listing, editor vault records, connector status, content-engine activation, run lookup, dispatch, and local-brain feed reads.</li>\n              <li>I connected the SovereignDocs vault UI to import returned SkyeDocxMax packages and kept local bridge fallbacks for browser-side handoffs.</li>\n              <li>I deployed the separate SovereignDocs Pages lane and redeployed the main 0S Worker so the mounted path serves the same live assets.</li>\n              <li>Production proof used an active FS27 admin session, created a live handoff, marked it opened, returned an edited package, and verified the returned package exists as a return, document, and vault record.</li>\n              <li>Content Engine live proof activated a package, listed the run, dispatched it without an external provider call, and verified the local-brain feed contains the proof chunk.</li>\n            </ul>\n            <div class=\"receipt-row\"><span><a href=\"../Free99/apps/sovereigndocs/vault/\">SovereignDocs vault</a></span><span><a href=\"../Free99/apps/sovereigndocs/skye-docx-max/app/\">SkyeDocxMax editor</a></span><span><code>test-artifacts/0s-interoperability/live-auth-write-proof-2026-05-20.json</code></span><span><code>test-artifacts/0s-interoperability/live-read-browser-proof-2026-05-20.json</code></span><span>Provider calls blocked</span><span>Tokens not persisted</span></div>\n          </div>\n        </article>\n\n        <article class=\"release-entry\" id=\"gate-owned-remote-quantumskyes-mcp\">\n          <div class=\"release-meta\">\n            <time class=\"release-date\" datetime=\"2026-05-20\">May 20, 2026</time>\n            <span class=\"release-version\">Gate-Owned Remote MCP</span>\n          </div>\n          <div class=\"release-body\">\n            <div class=\"tag-row\"><span>QuantumSkyes MCP</span><span>0S Gate</span><span>Owner Admin</span><span>Combined Introspection</span><span>Repo Runner</span><span>Live proof</span></div>\n            <h2>I turned the local design MCP into a gate-owned remote infrastructure lane.</h2>\n            <p>Skye Design MCP now runs as one public domain with a protected protocol endpoint: the lab stays public, <code>/use-mcp.html</code> explains access, <code>/health</code> proves the runtime, and <code>/mcp</code> accepts only gate-owned bearer sessions, signed owner-admin bearers, or owner-issued tokens.</p>\n            <ul class=\"release-points\">\n              <li>I kept the repo source of truth as <code>.mcp.json</code> -> <code>quantumskyes</code> -> <code>MCP/stdio-server.mjs</code> for local operator work.</li>\n              <li>I added a remote lane to <code>tools/use-my-mcp.mjs</code> so repo apps can switch to <code>MCP_TRANSPORT=remote</code> and mine through <code>https://skye-design-mcp.pages.dev/mcp</code>.</li>\n              <li>I added AI/operator documentation, a safe remote client config shape, package scripts, a 0S owner admin login, and a 0S command registry entry so agents know how to use the live MCP without committing bearer tokens.</li>\n              <li>Live proof created a synthetic FS27 gate signup, captured the email, introspected the returned session through combined 0S/FS27 introspection, and used that bearer session to list 31 resources and 27 tools from the deployed MCP.</li>\n              <li>The same proof ran the repo MCP runner against the deployed endpoint and refreshed <code>MCP/MCP_TOOLING_RECEIPT.json</code>, proving apps in this repo can hit the live MCP without relying on local stdio.</li>\n              <li>Unauthenticated protocol access still returns <code>401</code> with gate handoff metadata, so free access can remain email-owned and company-attributable.</li>\n            </ul>\n            <div class=\"receipt-row\"><span><a href=\"https://skye-design-mcp.pages.dev/use-mcp.html\" target=\"_blank\" rel=\"noreferrer\">Use MCP guide</a></span><span><a href=\"https://skye-design-mcp.pages.dev/health\" target=\"_blank\" rel=\"noreferrer\">Health proof</a></span><span><code>AI_REMOTE_MCP_USAGE.md</code></span><span><code>.mcp.remote.example.json</code></span><span><code>test-artifacts/skye-design-mcp-gate-owned-live/remote-gate-token-smoke.json</code></span><span>Tokens redacted</span></div>\n          </div>\n        </article>\n\n        <article class=\"release-entry\" id=\"fade-masters-open-source-northstar-repair\">\n          <div class=\"release-meta\">\n            <time class=\"release-date\" datetime=\"2026-05-20\">May 20, 2026</time>\n            <span class=\"release-version\">Fade Masters Media + NorthStar</span>\n          </div>\n          <div class=\"release-body\">\n            <div class=\"tag-row\"><span>Client App Factory</span><span>Fade Masters</span><span>Open-source media</span><span>NorthStar</span><span>SignInPro</span><span>Live proof</span></div>\n            <h2>I replaced the placeholder barber media, fixed the booking buttons, and made the Skyes-backed NorthStar lane visible.</h2>\n            <p>Fade Masters PHX now ships with the supplied HD open-source barber image pack, a rebuilt intro reel/poster, visible source/license attribution, working booking and walk-in queue controls, and a public request flow that mirrors into the NorthStar SignInPro workspace instead of merely claiming it.</p>\n            <ul class=\"release-points\">\n              <li>I moved <code>fade_masters_phx_open_source_hd_image_pack.zip</code> into the Fade Masters app, unpacked it, deleted the zip, and deployed only the web-ready pack files while keeping the huge original-image folder out of the 0S Worker assets.</li>\n              <li>I rebuilt <code>fade-masters-intro.mp4</code> and <code>fade-masters-shop-poster.jpg</code> from the supplied pack, then replaced the old weak gallery with six barber-chair, clipper, fade, mirror, razor, and storefront images plus source links.</li>\n              <li>I fixed the hero/nav booking and queue buttons so they close the intro overlay, scroll to the intended lane, and submit without being blocked by remote NorthStar auth checks.</li>\n              <li>I loaded <code>/northstar/assets/core.js</code> and <code>/northstar/assets/workspace-client.js</code> in the app, derive the workspace key through NorthStar, and mirror each request into <code>signinpro_workspace_state_v4:fade-masters-phx</code>.</li>\n              <li>I added the Skyes Over London deity mark and an <code>About SignIn Pro</code> tab to the NorthStar workspace login, including the 1,644-account field proof so users understand NorthStar is backed by Skyes Over London.</li>\n              <li>Local and live Playwright proof passed with 1920x1080 video, all six media images rendered, booking and queue receipts created, production shop-lane acceptance, SignInPro mirror count at <code>2</code>, NorthStar About tab visible, no failed responses, no console errors, no page errors, and mobile width clean at <code>390px</code>.</li>\n            </ul>\n            <div class=\"receipt-row\"><span><a href=\"../client-app-factory/client-apps/fade-masters-phx/\">Live Fade Masters app</a></span><span><a href=\"../northstar/?workspace=fade-masters-phx&amp;client=fade-masters-phx\">Protected NorthStar route</a></span><span><code>test-artifacts/fade-masters-phx-provided-media-northstar-2026-05-20/local-proof-report.json</code></span><span><code>test-artifacts/fade-masters-phx-provided-media-northstar-2026-05-20/live-proof-report.json</code></span><span><code>assets/media/fade-masters-phx-open-source-hd-image-pack/LICENSE_MANIFEST.md</code></span></div>\n          </div>\n        </article>\n\n        <article class=\"release-entry\" id=\"marketing-made-easy-ae-vendor-cloudflare-packet-vault\">\n          <div class=\"release-meta\">\n            <time class=\"release-date\" datetime=\"2026-05-20\">May 20, 2026</time>\n            <span class=\"release-version\">MME AE/Vendor Packet Vault</span>\n          </div>\n          <div class=\"release-body\">\n            <div class=\"tag-row\"><span>Marketing Made Easy</span><span>Cloudflare Worker</span><span>FS27/SkyGate</span><span>Encrypted KV</span><span>Live stress proof</span><span>No Netlify</span></div>\n            <h2>I moved AE/vendor onboarding onto the real 0S Cloudflare lane.</h2>\n            <p>The contractor packet form now submits to the live 0S Worker, uses the shared FS27/SkyGate session lane, stores W-9/agreement files and payout profile material in encrypted Cloudflare KV records, and keeps external payout transfer blocked until owner and provider gates are complete.</p>\n            <ul class=\"release-points\">\n              <li>I added the Cloudflare API routes for health, submit, packet list, packet read, and owner approval under <code>/api/marketing-made-easy/ae-vendor-onboarding/*</code>.</li>\n              <li>I replaced the old Netlify/Google Drive setup language with the Cloudflare packet vault guide and wired the browser form to send the inherited SkyGate session headers.</li>\n              <li>I configured the live Worker secret <code>AE_VENDOR_PACKET_ENCRYPTION_KEY_BASE64</code> and deployed Worker version <code>7dba7a59-49df-4eed-bc85-e9b1110b10ae</code>.</li>\n              <li>Live proof logged into FS27 as admin, verified the active SkyGate token, created a production packet, read it back, approved it, and confirmed no raw bank routing/account values were exposed.</li>\n              <li>Live stress proof submitted 20 concurrent authenticated production packets with 20 successes, 0 failures, 20 unique receipts, and all receipts visible in the packet ledger.</li>\n              <li>Local Worker-module proof still runs the bigger 80-concurrent stress suite so the production code path stays covered before deploy.</li>\n            </ul>\n            <div class=\"receipt-row\"><span><a href=\"../Marketing-Made-Easy/WebGrowthOperator/ae-command-hub/onboarding.html\">Onboarding form</a></span><span><a href=\"../api/marketing-made-easy/ae-vendor-onboarding/health\">Live health</a></span><span><code>test-artifacts/ae-vendor-onboarding-cloudflare/live-report.json</code></span><span><code>smoke-report.json</code></span><span><code>stress-report.json</code></span><span>No external transfer created</span></div>\n          </div>\n        </article>\n\n        <article class=\"release-entry\" id=\"fade-masters-owned-booking-lane\">\n          <div class=\"release-meta\">\n            <time class=\"release-date\" datetime=\"2026-05-20\">May 20, 2026</time>\n            <span class=\"release-version\">Fade Masters PHX Booking Lane</span>\n          </div>\n          <div class=\"release-body\">\n            <div class=\"tag-row\"><span>Client App Factory</span><span>Fade Masters</span><span>Booking</span><span>Walk-in queue</span><span>Shop intake</span><span>Live proof</span></div>\n            <h2>I replaced the generated template shell with a working booking and walk-in app.</h2>\n            <p>Fade Masters PHX now opens as a real customer-facing lane: service selection, appointment request, barber preference, walk-in queue, local receipts, and production shop-lane intake are all live under the 0S-mounted Client App Factory path.</p>\n            <ul class=\"release-points\">\n              <li>I removed the old generated video/media pack, white-label assets, fake contact/catalog claims, and unused storefront script from the app folder.</li>\n              <li>The retired generated routes now redirect into the booking app instead of showing catalog, blog, inventory, or preview-template pages.</li>\n              <li>The queue payload bug was fixed so production walk-in requests send the selected queue need, not the appointment services still selected on the page.</li>\n              <li>Final live Playwright proof submitted a booking and a walk-in request; both returned API <code>200</code>, and the queue API record carried <code>services: [\"Lineup only\"]</code>.</li>\n              <li>The service worker cache was bumped to <code>fade-masters-booking-v3</code> so returning browsers pick up the corrected behavior.</li>\n            </ul>\n            <div class=\"receipt-row\"><span><a href=\"../client-app-factory/client-apps/fade-masters-phx/\">Live booking app</a></span><span>App proof <code>a1abdb29-b5da-4e7b-84fa-75612b4caa10</code></span><span>Changelog live verified</span><span><code>test-artifacts/fade-masters-phx-proof-2026-05-20/production-proof-report.json</code></span><span><code>client-app-factory/client-apps/fade-masters-phx/MCP_TOOLING_RECEIPT.json</code></span><span>Old video assets 404</span></div>\n          </div>\n        </article>\n\n        <article class=\"release-entry\" id=\"sovereigndocs-legal-review-lane\">\n          <div class=\"release-meta\">\n            <time class=\"release-date\" datetime=\"2026-05-20\">May 20, 2026</time>\n            <span class=\"release-version\">SovereignDocs Legal Review</span>\n          </div>\n          <div class=\"release-body\">\n            <div class=\"tag-row\"><span>SovereignDocs</span><span>Valley Verified</span><span>Legal review lane</span><span>SkyePay</span><span>NorthStar SignIn Pro</span><span>Live proof</span></div>\n            <h2>I wired the legal review lane without pretending candidate firms are already partners.</h2>\n            <p>SovereignDocs now has a serious legal-review path: review packets store to the vault, create an upfront SkyePay checkout handoff, stay blocked from partner routing until payment and activation gates are handled, and produce a payout ledger entry after returned partner work is logged.</p>\n            <ul class=\"release-points\">\n              <li>I provisioned seven candidate legal workspaces for Burch &amp; Cracchiolo, Gallagher &amp; Kennedy, Fennemore, Greenberg Traurig Phoenix, Kutak Rock Scottsdale, Milligan Lawless, and PLATZ JURIS.</li>\n              <li>I kept the public language honest: candidate workspace only until outreach, bar/licensing verification, conflict rules, MSA/NDA, fee schedule, and payout destination are complete.</li>\n              <li>I added Valley Verified legal lane pages, client app handoff pages, NorthStar SignIn Pro workspace seeds, SovereignDocs partner-workbench routes, and partner network data.</li>\n              <li>I patched the 0S SovereignDocs Worker and local server for legal review submit, SkyePay checkout, vault record, payment confirmation, partner route/update, and payout ledger records.</li>\n              <li>I added the FS27 SkyePay offer <code>sovereigndocs-legal-review-lane</code> and deployed FS27 Worker version <code>6b11e610-030e-454d-88bb-27c9638b98d5</code>.</li>\n              <li>I deployed the 0S Worker legal lane and captured a live receipt for the legal lane, PLATZ JURIS lane page, app handoff, candidate JSON roster, SovereignDocs route manifest, protected API boundary, and SkyePay offer.</li>\n            </ul>\n            <div class=\"receipt-row\"><span><a href=\"../valley-verified/legal-review-lane/\">Legal lane</a></span><span><a href=\"../Free99/apps/sovereigndocs/review-submission/\">Submit review</a></span><span><a href=\"../client-app-factory/client-apps/platz-juris-pllc-phoenix-85016-4e77b1f/\">PLATZ app</a></span><span><code>test-artifacts/sovereigndocs-legal-review-live-proof.json</code></span><span><code>6b11e610-030e-454d-88bb-27c9638b98d5</code></span><span>Live receipt captured</span></div>\n          </div>\n        </article>\n\n        <article class=\"release-entry\" id=\"valley-verified-proof-integrity-factory-preview-boundary\">\n          <div class=\"release-meta\">\n            <time class=\"release-date\" datetime=\"2026-05-20\">May 20, 2026</time>\n            <span class=\"release-version\">Valley Verified Proof Integrity</span>\n          </div>\n          <div class=\"release-body\">\n            <div class=\"tag-row\"><span>Valley Verified</span><span>Fade Masters</span><span>Factory preview boundary</span><span>App-build lane</span><span>Proof integrity</span><span>0S mounted</span></div>\n            <h2>I stopped generated Client App Factory packages from being promoted as live owned apps.</h2>\n            <p>Fade Masters PHX and other generated factory packages now render as factory previews only, while unrelated Valley pages no longer inherit random app packages or actual-client-app language.</p>\n            <ul class=\"release-points\">\n              <li>I changed the Valley generator so factory packages direct-match only and do not spill into unrelated business pages.</li>\n              <li>Fade Masters PHX, Next Level Gaming, and the legal-review generated packages now say <code>Factory preview package</code>, <code>Open factory preview</code>, and <code>not a live owned app</code>.</li>\n              <li>Kitchell Corp. and other source-only pages are back to normal public/source pages with optional build paths instead of wrong generated app receipts.</li>\n              <li>The app-build route now says <code>Live builds and generated previews are separated</code> and uses <code>Open live build</code> for inspectable examples instead of the old generated-preview CTA.</li>\n              <li>The focused proof audit found zero old overclaim phrases across 1,146 mounted Valley files, with 9 factory-preview pages intentionally labeled as previews.</li>\n              <li>Browser proof hit Fade Masters, Kitchell, and App Builds locally with 200 responses and no old generated/actual-app claim text.</li>\n            </ul>\n            <div class=\"receipt-row\"><span><a href=\"../valley-verified/business/fade-masters-phx/\">Fade Masters PHX</a></span><span><a href=\"../valley-verified/app-builds/\">App Builds</a></span><span>Factory preview only</span><span>Generator updated</span><span><code>test-artifacts/valley-proof-integrity-2026-05-20/factory-preview-boundary-report.json</code></span><span>Production verified live</span></div>\n          </div>\n        </article>\n\n        <article class=\"release-entry\" id=\"guided-tour-public-route-repair\">\n          <div class=\"release-meta\">\n            <time class=\"release-date\" datetime=\"2026-05-20\">May 20, 2026</time>\n            <span class=\"release-version\">Guided Tours</span>\n          </div>\n          <div class=\"release-body\">\n            <div class=\"tag-row\"><span>0S walkthroughs</span><span>Training Academy</span><span>SkyeMail</span><span>SOL Staffing</span><span>Live Playwright proof</span><span>Public redirects</span></div>\n            <h2>I repaired the two tutorial entrypoints that were still falling into the private source block.</h2>\n            <p>The public 0S tutorial sweep now records the walkthrough center, training academy, admin tutorial set, role training pages, onboarding rooms, and guided first-run journey as live. The two raw <code>/live</code> tutorial URLs now redirect into their dedicated gated systems instead of returning the private-source 404.</p>\n            <ul class=\"release-points\">\n              <li>Live Playwright checked 50 focused tutorial, walkthrough, training, and onboarding targets; 48 public 0S routes passed, and the remaining two are now public redirects to dedicated gated systems.</li>\n              <li>The first-run guide was proven live in Chromium from the walkthrough center to the command surface, then advanced from Step 1 to Step 2 with the runtime truth widget no longer intercepting guide controls.</li>\n              <li>The 0S Worker redirects <code>/live/sol_staffing_agency_site/training-academy.html</code> to <code>https://sol-staffing-agency-site.pages.dev/training-academy.html</code>, which lands on the staffing login gate for that academy route.</li>\n              <li>The 0S Worker redirects <code>/live/SkyeMail/onboarding.html</code> to <code>https://skyemail-platform.graylondonskyes.workers.dev/onboarding.html</code>, which lands on the SkyeMail gated onboarding lane.</li>\n              <li>The repair keeps raw <code>/live</code> source folders private while making the intended 0S entrypoints operational for users.</li>\n            </ul>\n            <div class=\"receipt-row\"><span>50 live targets</span><span>First-run guide advanced</span><span>SOL 302 to gate</span><span>SkyeMail 302 to gate</span><span>Raw /live stays private</span></div>\n          </div>\n        </article>\n\n        <article class=\"release-entry\" id=\"valley-verified-video-layout-repair\">\n          <div class=\"release-meta\">\n            <time class=\"release-date\" datetime=\"2026-05-20\">May 20, 2026</time>\n            <span class=\"release-version\">Valley Verified Video Layout</span>\n          </div>\n          <div class=\"release-body\">\n            <div class=\"tag-row\"><span>Valley Verified</span><span>Video-first layout</span><span>App-build pages</span><span>Business landings</span><span>Generator fix</span><span>0S mounted</span></div>\n            <h2>I gave Valley Verified videos their own top-owned space instead of treating them like a side column.</h2>\n            <p>The shared Valley Verified app-build and business landing layouts now stack video/media above the copy blocks, so preview footage owns the section instead of getting squeezed beside the text. I fixed this at the source layer and the generator layer so the rule applies across the verified site, not just one client page.</p>\n            <ul class=\"release-points\">\n              <li>I changed the shared Valley styles for <code>.vv-app-client-shell</code>, <code>.actual-client-app-shell</code>, <code>.actual-client-card</code>, and <code>.app-case-study</code> from side-by-side columns to one-column stacked media-first layouts.</li>\n              <li>I updated the injected v23 generator CSS so rebuilt app-build pages inherit the same rule instead of reintroducing the old two-column squeeze on the next build.</li>\n              <li>I rebuilt the Valley Verified source bundle, synced it back into the mounted 0S Valley folder, and redeployed the live 0S worker so the change reaches the public <code>/valley-verified/</code> route.</li>\n              <li>The live Fade Masters PHX route was used as the browser check because it showed the problem clearly before the fix and now renders with the video stacked above the copy block.</li>\n              <li>This repair was published on 0S worker version <code>fab47ea9-8592-4796-b71b-69b1bddcb2e8</code>.</li>\n            </ul>\n            <div class=\"receipt-row\"><span><a href=\"../valley-verified/business/fade-masters-phx/\">Fade Masters PHX</a></span><span><a href=\"../valley-verified/app-builds/\">App Builds</a></span><span>Stacked media-first</span><span>Generator updated</span><span>Mounted 0S sync</span><span><code>fab47ea9-8592-4796-b71b-69b1bddcb2e8</code></span></div>\n          </div>\n        </article>\n\n        <article class=\"release-entry\" id=\"fs27-contact-ecology-live-proof\">\n          <div class=\"release-meta\">\n            <time class=\"release-date\" datetime=\"2026-05-20\">May 20, 2026</time>\n            <span class=\"release-version\">Contact Ecology</span>\n          </div>\n          <div class=\"release-body\">\n            <div class=\"tag-row\"><span>FS27 contact intake</span><span>Skyes reviews</span><span>Request service</span><span>0S Relay13 binding</span><span>ConnectLog</span><span>Browser proof</span></div>\n            <h2>I moved the public contact, review, and service-request flow into one FS27-owned intake ecology.</h2>\n            <p>The public Skyes Over London review wall now has a real service request lane, review submissions route into FS27 contact intake, operator review QA uses FS27 admin authority, and fallback email stays backup-only instead of the primary workflow.</p>\n            <ul class=\"release-points\">\n              <li>I deployed FS27 Worker version <code>8a91ac76-6ca8-47c5-99cf-026f91dc26c9</code> with <code>/api/contact/intake</code>, <code>/admin/contact-intake</code>, and the private Contact Intake Admin surface.</li>\n              <li>I deployed the Skyes Over London Reviews Pages site with <code>request-service.html</code>, FS27 review submission wiring, normalized review-wall links, and the existing fallback <code>mailto:skyesoverlondon@gmail.com</code> only for outages.</li>\n              <li>Live API proof created a private service request, returned an FS27 receipt, sent the Resend backup email, proved admin read with existing FS27/free99-style authority, then marked the proof record triaged.</li>\n              <li>Live Playwright proof submitted through the public request-service page, received a visible FS27 receipt, found the record in admin, closed it, checked review intake and operator queue pages, and recorded zero console/page errors or horizontal overflow.</li>\n              <li>I corrected Relay13 from a fake provider-key boundary to first-party infrastructure: FS27/Gate intake now calls the 0S Worker by service binding, and 0S routes the handoff into Relay13/ConnectLog.</li>\n              <li>Final live proof returned <code>relay_status: sent</code>, <code>relay_receipt.mode: relay13_0s_service_binding</code>, <code>route: 0s_service_binding</code>, <code>bridge: connectlog</code>, Relay13 status <code>201</code>, and backup email <code>sent</code>.</li>\n              <li>I removed the public <code>workers.dev</code> HTTP call from the production inter-worker delivery chain: with the 0S service binding present, FS27 no longer attempts that URL and the proof confirms no public-HTTP fallback 404.</li>\n            </ul>\n            <div class=\"receipt-row\"><span>FS27 receipt</span><span>0S binding sent</span><span>ConnectLog bridged</span><span>Admin read passed</span><span>Resend sent</span><span>Playwright clean</span></div>\n          </div>\n        </article>\n\n        <article class=\"release-entry\" id=\"client-factory-and-webcreator-live-auren-proof\">\n          <div class=\"release-meta\">\n            <time class=\"release-date\" datetime=\"2026-05-20\">May 20, 2026</time>\n            <span class=\"release-version\">Auren Live Builder Proof</span>\n          </div>\n          <div class=\"release-body\">\n            <div class=\"tag-row\"><span>Client App Factory</span><span>SkyeWebCreatorMax</span><span>Auren</span><span>Valley Verified</span><span>Public Playwright proof</span><span>Workers live</span></div>\n            <h2>I pushed the live builder lanes through public browser proof so the factory and web creator now answer with real Auren help on the 0S Worker.</h2>\n            <p>The live 0S Worker now serves a usable public client-factory path and a usable SkyeWebCreatorMax builder path with <code>OPENAI_MODEL=gpt-4.1-mini</code>, <code>VANTA_ALLOW_LIVE_AI=1</code>, and the production OpenAI secret bound on the Worker. I verified both surfaces against the public <code>workers.dev</code> URL, not just local mirrors.</p>\n            <ul class=\"release-points\">\n              <li>The mounted Client App Factory now loads Valley Verified businesses on the public Worker, imports <strong>As You Wish Pottery</strong>, completes the full factory run, opens the generated app route, loads scanner/proof lanes, catalogs a proof asset, and verifies proof-video playback.</li>\n              <li>The public SkyeWebCreatorMax builder now reaches the live Auren lane, keeps the live toggle enabled, returns <code>openai:gpt-4.1-mini</code> responses, renders prompts/issues/actions, and stays free of console errors, request failures, and horizontal overflow on desktop and mobile.</li>\n              <li>I removed the edge auth block that was still choking the factory namespace before the adapter could answer, then redeployed the full 0S Worker with the correct config instead of letting Wrangler wander into a nested app.</li>\n              <li>The public factory health and public web creator runtime status now both report <code>configured: true</code> and <code>liveAvailable: true</code> for AI.</li>\n              <li>This push was proven on live Worker version <code>dcb7510b-f388-48ba-a9a3-15a46fca2cc8</code>.</li>\n            </ul>\n            <div class=\"receipt-row\"><span><a href=\"../client-app-factory/\">Mounted factory shell</a></span><span><a href=\"../Marketing-Made-Easy/SkyeWebCreatorMax/builder.html\">SkyeWebCreatorMax builder</a></span><span><a href=\"../api/client-app-factory/health\">Factory health</a></span><span><a href=\"../api/marketing-made-easy/webcreator-runtime/status\">Web creator runtime status</a></span><span><code>test-artifacts/client-app-factory/browser-proof.json</code></span><span><code>test-artifacts/skye-web-creator/builder-auren-proof.json</code></span></div>\n          </div>\n        </article>\n\n        <article class=\"release-entry\" id=\"marketing-made-easy-mounted-platform\">\n          <div class=\"release-meta\">\n            <time class=\"release-date\" datetime=\"2026-05-20\">May 20, 2026</time>\n            <span class=\"release-version\">MME Mounted Platform</span>\n          </div>\n          <div class=\"release-body\">\n            <div class=\"tag-row\"><span>Marketing Made Easy</span><span>NorthStar rule</span><span>One gate lane</span><span>Workspace routing</span><span>Free99</span><span>Production live</span></div>\n            <h2>I promoted Marketing Made Easy from a scanned suite into a real mounted 0S platform.</h2>\n            <p>Marketing Made Easy now runs the NorthStar way on the live 0S domain: one platform shell, one namespaced API lane, one shared FS27/SkyGate auth lane, workspace routing, and Free99 access that is still gate-owned and rate-limited. The 8 internal rooms still keep their own UI, but they do not get to go rogue with standalone production auth or root <code>/api/runtime/*</code> ownership.</p>\n            <ul class=\"release-points\">\n              <li>The live shell at <code>/Marketing-Made-Easy/</code> now loads as the real mounted platform entry instead of reading like a proof-only holding page.</li>\n              <li>The 0S Worker now serves <code>/api/marketing-made-easy/health</code>, <code>/api/marketing-made-easy/platform/manifest</code>, catalog routes, gated session reads, workspace reads, brief intake, and board/audit lanes under the shared gate model.</li>\n              <li>Unauthenticated session reads now return <code>401</code>, which proves the platform is inheriting the same auth lane as NorthStar instead of inventing a second login world.</li>\n              <li>The old root <code>/api/runtime/*</code> lane stays blocked as a collision diagnostic so MME can only operate through its owned namespace.</li>\n              <li>I rewrote the public shell copy so it explicitly says <code>One platform shell. One gate lane. Eight working rooms inside it.</code> and points to the live manifest/catalog surfaces.</li>\n            </ul>\n            <div class=\"receipt-row\"><span><a href=\"../Marketing-Made-Easy/\">Mounted shell</a></span><span><a href=\"../live/marketing-made-easy-growth-suite.html\">0S live hub</a></span><span><a href=\"../api/marketing-made-easy/health\">Health</a></span><span><a href=\"../api/marketing-made-easy/platform/manifest\">Manifest</a></span><span>8 module rooms</span><span><code>test-artifacts/0s-surface/marketing-made-easy-northstar-platform-proof-2026-05-20.json</code></span></div>\n          </div>\n        </article>\n\n        <article class=\"release-entry\" id=\"skyevault-one-auth-receipt-command-center\">\n          <div class=\"release-meta\">\n            <time class=\"release-date\" datetime=\"2026-05-20\">May 20, 2026</time>\n            <span class=\"release-version\">SkyeVault One-Auth Receipts</span>\n          </div>\n          <div class=\"release-body\">\n            <div class=\"tag-row\"><span>SkyeVault</span><span>FS27 one-auth</span><span>0S command center</span><span>Signed downloads</span><span>SkyeSecure handoff</span><span>Production proved</span></div>\n            <h2>I closed the vault custody gap so admin receipt access now runs through FS27 one-auth and produces live proof.</h2>\n            <p>The 0S now has a SkyeVault Command Center that loads the production SkyeVault ledger with an active FS27 admin bearer, opens signed vault download links, routes <code>.skyesecrets</code> receipts into the SkyeSecure unlock console, and writes actor-stamped SkyeVault audit events instead of relying on loose artifact-only custody.</p>\n            <ul class=\"release-points\">\n              <li>FS27 admin login JWTs now introspect as active admin bearers with <code>admin.read</code>, <code>admin.write</code>, <code>keys.write</code>, <code>gateway.invoke</code>, and <code>skyevault.admin</code> scope.</li>\n              <li>SkyeVault Drop accepts FS27 bearer auth through a Cloudflare service binding to <code>skyegatefs27-citadeldb</code> and returns <code>actor.type = fs27-skygate</code> for the receipt dashboard.</li>\n              <li>SkyeVault admin config, export, health, and signed-download events now stamp actor, auth type, workspace, customer, and gate-card context into the audit trail.</li>\n              <li>The live 0S command center at <code>/admin/skyevault-command-center.html</code> can load receipts, export ledger JSON, create signed downloads, and send secret packs to SkyeSecure.</li>\n              <li>The repo vault push tool now accepts workspace, customer, repo, developer, gate card, API key, role, destination, client name, and client email metadata flags for future identity-stamped uploads.</li>\n              <li>Production proof passed after deploy: 0S command center ok, FS27 one-auth ok, and signed receipt download ok for receipt <code>cdv_54b7ae793fd457cb91bde1a3</code>.</li>\n            </ul>\n            <div class=\"receipt-row\"><span><a href=\"../admin/skyevault-command-center.html\">0S SkyeVault Command Center</a></span><span><a href=\"https://skyevault-drop.graylondonskyes.workers.dev/\" target=\"_blank\" rel=\"noreferrer\">SkyeVault Drop Worker</a></span><span>FS27 Worker <code>10a6a3dd-2eb0-4a76-a0d8-e0eb6ff86815</code></span><span>SkyeVault Worker <code>873e2031-05b7-4dac-b963-646e9ab9f309</code></span><span>0S Worker <code>4e66bafa-b78b-41e3-9806-06ae7d67096d</code></span><span>Proof <code>test-artifacts/skyevault-one-auth-live-proof/skyevault-one-auth-live-proof-20260520T035539Z.json</code></span></div>\n          </div>\n        </article>\n\n        <article class=\"release-entry\" id=\"fs27-one-gate-0s-auth-ownership\">\n          <div class=\"release-meta\">\n            <time class=\"release-date\" datetime=\"2026-05-20\">May 20, 2026</time>\n            <span class=\"release-version\">FS27 One Gate Ownership</span>\n          </div>\n          <div class=\"release-body\">\n            <div class=\"tag-row\"><span>0S Gate</span><span>FS27 Core</span><span>SkyGate</span><span>Gate cards</span><span>AI ownership</span><span>Production pushed</span></div>\n            <h2>I moved the live gate into the 0S and made the mounted app lanes inherit FS27 authority instead of asking users for standalone keys.</h2>\n            <p>The current 0S production build treats SkyGateFS27 as the mega auth layer inside MetrAIyux 0S. The single local gate source now lives under <code>metraiyux_0s_site/skyegate/source/SkyeGateFS27/</code>, the 0S launcher opens the 0S SkyGate platform, and the shared bridge sends gate-card, role, customer, workspace, and client context into app calls.</p>\n            <ul class=\"release-points\">\n              <li>The old root <code>SkyeGateFS27</code> runnable path is gone; root scripts now point at the 0S-owned gate source.</li>\n              <li>The browser bridge no longer trusts old local aliases such as <code>kx.api.accessToken</code>, <code>kaixu_api_key</code>, or <code>KAIXU_VIRTUAL_KEY</code> as app authority.</li>\n              <li>FS27 push and GitHub lanes now resolve shared 0S/SkyGate sessions through gate auth instead of teaching apps to ask for Kaixu keys.</li>\n              <li>SkyeMail login now continues with the inherited 0S/SkyGate session and no longer shows a manual gate-token field.</li>\n              <li>Live proof confirmed the 0S SkyGate page says <code>Single Gate Source</code>, the live bridge emits gate-card/customer headers, and FS27 app UI asks for an admin 0S/SkyGate session where admin scope is required.</li>\n            </ul>\n            <div class=\"receipt-row\"><span>0S Worker <code>bf22ef72-397b-462f-b3ee-8bb4c6d1d112</code></span><span>FS27 Worker <code>f7d69577-a0a4-40e5-b8a2-30c6db2269d3</code></span><span>SkyeMail Worker <code>6b28eec4-1012-4e46-bb42-fcc61abfbc20</code></span><span><a href=\"../skyegate/index.html\">0S SkyGate</a></span><span><a href=\"../audits/0S_GATE_CARD_AUTH_DRIFT_AUDIT_2026-05-19.md\">Gate audit receipt</a></span></div>\n          </div>\n        </article>\n\n        <article class=\"release-entry\" id=\"relay13-ai-response-lanes-managed-inbox\">\n          <div class=\"release-meta\">\n            <time class=\"release-date\" datetime=\"2026-05-20\">May 20, 2026</time>\n            <span class=\"release-version\">Relay13 AI Response Lanes</span>\n          </div>\n          <div class=\"release-body\">\n            <div class=\"tag-row\"><span>Relay13</span><span>Managed AI Inbox</span><span>Backup buckets</span><span>SkyePay</span><span>Monitors</span><span>Stress tested</span></div>\n            <h2>I turned the single AI add-on into three coded lanes with backup buckets, no-loss fallback, and real managed-inbox behavior.</h2>\n            <p>The 0S now has a canonical Relay13 AI lane policy module for Starter, Response Plus, and Managed AI Inbox. The router caps paid provider calls, activates backup buckets before hard stop, keeps every lead captured through FS27/Relay13/ConnectLog, and lets the Managed AI Inbox actually triage, label, send allowlisted routine replies, start follow-up timers, summarize to ConnectLog, and escalate risky messages.</p>\n            <ul class=\"release-points\">\n              <li>Starter is <strong>$35/mo</strong> with <strong>125 included messages</strong> plus a <strong>31-message backup bucket</strong>.</li>\n              <li>Response Plus is <strong>$79/mo</strong> with <strong>425 included messages</strong> plus a <strong>76-message backup bucket</strong>.</li>\n              <li>Managed AI Inbox starts at <strong>$149/mo</strong> with <strong>1,000 included messages</strong> plus a <strong>222-message backup bucket</strong>.</li>\n              <li>Offer ids are explicit for SkyePay and monitor wiring: <code>relay13-ai-response-starter</code>, <code>relay13-ai-response-plus</code>, and <code>relay13-managed-ai-inbox</code>.</li>\n              <li>The factory backend and mounted 0S factory adapter now expose AI response plan, route, monitor, and stress endpoints.</li>\n              <li>The public marketing home, marketplace, sell sheet, Relay13 value page, Relay13 tutorial, root factory, and mounted factory shell now explain the three lanes consistently.</li>\n            </ul>\n            <div class=\"receipt-row\"><span><code>cloudflare/relay13-ai-lanes.mjs</code></span><span><code>/api/factory/ai-response/plans</code></span><span><code>/api/client-app-factory/factory/ai-response/stress</code></span><span>Lead-loss risk: false</span><span>Provider calls capped</span><span>test-artifacts/relay13-ai-response-lanes/monitor-stress-report.json</span></div>\n          </div>\n        </article>\n\n        <article class=\"release-entry\" id=\"client-app-operating-loop-ai-response-starter\">\n          <div class=\"release-meta\">\n            <time class=\"release-date\" datetime=\"2026-05-20\">May 20, 2026</time>\n            <span class=\"release-version\">Client App Operating Loop</span>\n          </div>\n          <div class=\"release-body\">\n            <div class=\"tag-row\"><span>Client apps</span><span>FS27 leads</span><span>Relay13</span><span>ConnectLog</span><span>SkyePay</span><span>AI add-on</span><span>Live verified</span></div>\n            <h2>I made the public 0S explain exactly what a client can do with their app, how the lead path works, and where the paid AI response add-on begins.</h2>\n            <p>The marketing site, marketplace, sell sheet, Relay13 value page, Relay13 client tutorial, root client-app factory, and mounted 0S factory shell now describe the real operating loop: a customer scans or opens a client app, the request is captured, FS27 receives the lead/contact/activity record, Relay13 creates the workspace thread, ConnectLog keeps the follow-up trail, and the owner replies directly, routes it through the local brain, or activates the paid AI draft layer.</p>\n            <ul class=\"release-points\">\n              <li>The public marketing home now has a Client App Operating Loop section that tells clients what happens after their app is live and what work they can run from it.</li>\n              <li>The marketplace now separates the core ConnectLog + Relay13 infrastructure from optional paid Relay13 AI response lanes with owner-reviewed drafts and no-loss fallback.</li>\n              <li>The Relay13 tutorial now gives the owner flow clearly: direct reply, local brain response, paid AI draft, ConnectLog follow-up, and Gate escalation when needed.</li>\n              <li>The client-app factory workspace room now mirrors the same handoff language so generated client workspaces explain lead capture, workspace delivery, local automation, and paid AI boundaries without pretending every message uses a paid model.</li>\n              <li>I published the refreshed factory shell into the mounted 0S copy so the standalone factory and the 0S-mounted factory tell the same story.</li>\n              <li>Browser proof covered seven live URLs after deploy with status 200 and working scroll, including marketing home, marketplace, sell sheet, Relay13 value, Relay13 tutorial, standalone factory, and mounted 0S factory.</li>\n            </ul>\n            <div class=\"receipt-row\"><span><a href=\"../client-app-factory/\">0S-mounted factory</a></span><span><a href=\"../live/relay13-what-you-get.html\">Relay13 value page</a></span><span><a href=\"../live/relay13-client-tutorial.html\">Relay13 tutorial</a></span><span><a href=\"https://metraiyux-0s-marketing.pages.dev/index.html#client-operating-loop\" target=\"_blank\" rel=\"noreferrer\">Marketing loop</a></span><span><a href=\"https://metraiyux-0s-marketing.pages.dev/marketplace.html#skye-suite\" target=\"_blank\" rel=\"noreferrer\">Marketplace add-on</a></span><span>0S Worker redeployed after changelog update</span><span>test-artifacts/public-marketing-closure/live-playwright-report.json</span></div>\n          </div>\n        </article>\n\n        <article class=\"release-entry\" id=\"vaultos-skysecure-public-surface-proof\">\n          <div class=\"release-meta\">\n            <time class=\"release-date\" datetime=\"2026-05-20\">May 20, 2026</time>\n            <span class=\"release-version\">VaultOS Public Surface Proof</span>\n          </div>\n          <div class=\"release-body\">\n            <div class=\"tag-row\"><span>Public surfaces</span><span>Live sweep</span><span>SkySecure</span><span>SkyeVaultOS</span><span>FS27 metadata</span><span>Proof receipt</span></div>\n            <h2>I refreshed the public 0S story so clients see the proven VaultOS capability, not stale claims.</h2>\n            <p>The public 0S VaultOS/SkySecure lane now says exactly what is proven live: FS27 metadata APIs, 18 command coverage, 1,833 scanned and restored files, four encrypted VaultOS objects, portable bundle export, attach into a fresh vault, reload, clean diffs, restore-point creation, audit evidence, and FS27 sync.</p>\n            <ul class=\"release-points\">\n              <li>I updated the home route cards, SkyeWay, Feature Atlas, SkySecure Platform Console, Proof Vault index, SkySecure FS27 proof receipt, changelog, audit doc, SkyeRunners brain, live-surface registry, platform ledger, and deployment ledger language for the current capability story.</li>\n              <li>I separated the May 19 SkySecure encrypted secret-pack proof from the May 20 SkyeVaultOS delete-candidate proof so the old 3-pack/3-grant/9-event result does not hide the larger VaultOS proof.</li>\n              <li>The live sweep checked 20 URLs after deployment and returned 0 failures, including FS27 proof, commands, inventory, search, restore-points, audit, and SkySecure proof routes.</li>\n              <li>The SkyeRunners brain now reads the live FS27 sync receipt and reports <code>fs27_sync_ok=true</code> with 6 synced metadata writes.</li>\n              <li>The public boundary remains secret-safe: no plaintext secrets, admin passwords, passphrases, encrypted download links, or raw secret file contents are published.</li>\n            </ul>\n            <div class=\"receipt-row\"><span>0S Worker <code>88473569-d9e8-43f1-93db-8b9aa0b22d41</code></span><span>20 live URL checks</span><span>0 failures</span><span>FS27 inventory: 1,833 files</span><span>FS27 audit: 4 events</span><span>test-artifacts/vaultos-public-surface-proof</span></div>\n          </div>\n        </article>\n\n        <article class=\"release-entry\" id=\"skyevaultos-skysecure-vault-console\">\n          <div class=\"release-meta\">\n            <time class=\"release-date\" datetime=\"2026-05-19\">May 19, 2026</time>\n            <span class=\"release-version\">SkyeVaultOS Console</span>\n          </div>\n          <div class=\"release-body\">\n            <div class=\"tag-row\"><span>SkyeVaultOS</span><span>SkySecure</span><span>FS27 APIs</span><span>Drive bundle</span><span>Restore point</span><span>SkyeRunners</span></div>\n            <h2>I wired the delete-candidate vault console, drive-bundle handoff, and live FS27 metadata APIs.</h2>\n            <p>SkyeVaultOS now gives the 0S a unified CLI, public console, FS27 live-system proof metadata routes, SkyeRunners command, bash-native inspection, portable bundle export/attach, and live inventory/search/restore-point/audit APIs for scan, offload, inventory, search, diff, verify, reload, restore-point, grant, revoke, and audit before anything gets deleted.</p>\n            <ul class=\"release-points\">\n              <li>I ran the live system proof against <code>/workspaces/MetrAIyux-0S/about to delete</code> and preserved the original folder.</li>\n              <li>The folder scanned as 1,833 files and 503,761,494 plaintext bytes, then encrypted into a four-object VaultOS pack set because a single pack hit runtime string limits.</li>\n              <li>Source diff, reload diff, and bundle reload diff all passed with 1,833 verified files, 0 missing, 0 changed, 0 extra, and 0 scan errors.</li>\n              <li>The proof covered scan, offload, inventory, search, diff, verify, dry reload, real reload, restore-point, grant, revoke, audit, ls, tree, cat-meta, manifest, bundle, attach, fs27-sync, desktop/mobile browser rendering, and deployed FS27 route health.</li>\n              <li>The FS27 VaultOS routes now publish proof, commands, inventory, search, restore-point, and audit metadata; they do not accept plaintext secret payloads or public download links.</li>\n              <li>I refreshed and live-swept the public 0S surfaces for the current capability story: home, SkyeWay, Feature Atlas, SkySecure Platform Console, Proof Vault, SkySecure proof receipt, changelog, audit doc, SkyeRunners brain, live surface registry, platform ledger, and FS27 VaultOS metadata routes. The post-deploy sweep checked 20 URLs with 0 failures.</li>\n              <li>Execution scope is explicit: filesystem operations ran from CLI/app proof storage, while FS27 and 0S routes are deployed live.</li>\n            </ul>\n            <div class=\"receipt-row\"><span><a href=\"../skye-vault-os/\">VaultOS console</a></span><span><a href=\"https://skyegatefs27-citadeldb.graylondonskyes.workers.dev/skysecure/vaultos/inventory\" target=\"_blank\" rel=\"noreferrer\">FS27 inventory API</a></span><span>test-artifacts/vaultos-about-to-delete-proof</span><span>test-artifacts/vaultos-public-surface-proof</span><span>18 commands</span><span>20 live URL checks / 0 failures</span></div>\n          </div>\n        </article>\n\n        <article class=\"release-entry\" id=\"vantacore-service-crm-ownership\">\n          <div class=\"release-meta\">\n            <time class=\"release-date\" datetime=\"2026-05-20\">May 20, 2026</time>\n            <span class=\"release-version\">VantaCore Owned Lane Live Proof</span>\n          </div>\n          <div class=\"release-body\">\n            <div class=\"tag-row\"><span>VantaCore</span><span>Inherited auth</span><span>Actual CRM workspace</span><span>Provider control</span><span>Live stress</span><span>0S overlap</span></div>\n            <h2>I made VantaCore an FS27-owned lane and proved it live end to end.</h2>\n            <p>The VantaCore CRM workspace now inherits 0S/Free99/FS27 authority, uses the persisted `/api/vantacore/crm` routes, and is accounted for as a service-business intake lane instead of a duplicate auth, messaging, mail, payment, records, dispatch, or provisioning system.</p>\n            <ul class=\"release-points\">\n              <li>I removed the Vanta-owned auth path: no Vanta login form, password reset, saved session, admin-login call, or password-header shortcut remains for the CRM workspace.</li>\n              <li>I bridged the central FS27 login into session-scoped inherited gate keys so the existing admin password mints one FS27 token and Vanta opens from that authority.</li>\n              <li>I mounted the FS27 <code>admin-customers</code> route so the live admin UI no longer clears a successful login during its first customer-table load.</li>\n              <li>I live-tested FS27 Worker version <code>57d80970-d429-4036-a60d-50c8ec66d479</code>: no-auth and direct Vanta password-header requests rejected, central FS27 login accepted, 8 write cycles passed, 96 concurrent reads returned 200, Playwright proved the dashboard workflow on desktop/mobile, and the actual FS27 admin password UI opened Vanta from the inherited session.</li>\n              <li>I added the FS27 provider-control pass on Worker version <code>ad14aab5-e12e-4e17-a8eb-8b2424b823e6</code>: Twilio, Resend, Google Calendar, SkyePay/Stripe, storage, provisioning handoff, and rollback receipts are selected and dry-run proven through VantaCore receipts; the public review destination remains private-feedback-first until a real review URL is configured.</li>\n            </ul>\n            <div class=\"receipt-row\"><span><a href=\"https://skyegatefs27-citadeldb.graylondonskyes.workers.dev/vantacore-crm\" target=\"_blank\" rel=\"noreferrer\">Actual CRM workspace</a></span><span><a href=\"../live/vantacore-service-crm-operator-proof.html\">0S hub</a></span><span><a href=\"../proof/vantacore-service-crm-expansion-receipt.html\">Proof receipt</a></span><span><a href=\"../audits/VANTACORE_OWNED_LANE_LIVE_PROOF_AND_OVERLAP_2026-05-20.md\">Overlap audit</a></span><span>7 provider dry-runs</span><span>96 live reads</span></div>\n          </div>\n        </article>\n\n        <article class=\"release-entry\" id=\"sovereigndocs-term-help-editor\">\n          <div class=\"release-meta\">\n            <time class=\"release-date\" datetime=\"2026-05-20\">May 20, 2026</time>\n            <span class=\"release-version\">SovereignDocs Term Help</span>\n          </div>\n          <div class=\"release-body\">\n            <div class=\"tag-row\"><span>SovereignDocs</span><span>Builder glossary</span><span>SkyeDocxMax Terms panel</span><span>Question mark help</span><span>Mobile QA</span><span>MCP receipt</span></div>\n            <h2>I added plain-language document term help where clients actually get confused.</h2>\n            <p>The builder and full document editor now explain terms like principal, LLC, registered agent, governing law, jurisdiction, effective date, acknowledgment, and operating agreement from the surface where the client is typing.</p>\n            <ul class=\"release-points\">\n              <li>I added question-mark help buttons to SovereignDocs builder fields and official-source prep fields, plus detected-term chips for the current template.</li>\n              <li>I added a SkyeDocxMax Terms tab in the review console, a header help button, detected term cards, and question-mark modal explanations inside the editor.</li>\n              <li>I kept the boundary explicit: explanations are plain-language helpers, not legal advice or proof that a document is state-compliant.</li>\n              <li>I cleaned negative letter-spacing in the SovereignDocs target so the MCP validation passes and mobile labels are less likely to clip.</li>\n              <li>I rebuilt the separate SovereignDocs lane and verified desktop/mobile builder and editor behavior with Playwright before deployment.</li>\n              <li>I repaired the Word-compatible export path so <code>.doc</code> downloads are branded HTML documents with the light SKYESOVERLONDON Deity-logo watermark background, then stress-tested 60 builder exports and 2 workspace exports through the live 0S-mounted route with zero failures.</li>\n            </ul>\n            <div class=\"receipt-row\"><span><a href=\"../Free99/apps/sovereigndocs/builder/\">Builder</a></span><span><a href=\"../Free99/apps/sovereigndocs/skye-docx-max/app/\">SkyeDocxMax editor</a></span><span>10,976 lane files</span><span>66 live Playwright checks</span><span>62 export stress passes</span><span>test-artifacts/sovereigndocs-0s-lane/export-stress-proof/EXPORT_STRESS_PROOF.json</span></div>\n          </div>\n        </article>\n\n        <article class=\"release-entry\" id=\"sovereigndocs-official-prep-lane\">\n          <div class=\"release-meta\">\n            <time class=\"release-date\" datetime=\"2026-05-20\">May 20, 2026</time>\n            <span class=\"release-version\">SovereignDocs Prep Lane Repair</span>\n          </div>\n          <div class=\"release-body\">\n            <div class=\"tag-row\"><span>SovereignDocs</span><span>Real logo</span><span>Prep packets</span><span>Official-source boundary</span><span>0S static lane</span><span>Browser QA</span></div>\n            <h2>I replaced the weak brand shell and made official-source workflows do real prep work.</h2>\n            <p>SovereignDocs now uses a real SVG seal and lockup across the app, and the official-source pages generate prep packets instead of presenting external links as the whole workflow.</p>\n            <ul class=\"release-points\">\n              <li>I added the SovereignDocs mark, full logo lockup, and install icon, then wired the nav mark and first viewport to those assets instead of a generic initials badge.</li>\n              <li>I changed public language from broad official-source workflow claims to prep workflow language with the correct boundary: SovereignDocs prepares packets and checklists, while the final filing or submission happens on the external official site unless a separately proven live integration exists.</li>\n              <li>I added interactive prep packet forms on the official-source page and the official workflow studio, with local packet storage, audit events, packet JSON, checklist markdown, and a clear <code>sovereignDocsSubmitted=false</code> record.</li>\n              <li>I added the mounted 0S API route for persisted official prep packets: <code>POST /api/sovereigndocs/official-workflows/prepare</code> and <code>GET /api/sovereigndocs/official-workflows/packets</code>.</li>\n              <li>I rebuilt the separate SovereignDocs 0S lane and verified desktop/mobile browser behavior: logo render, MCP visual chrome, no horizontal overflow, document library load, builder load, prep packet generation, scoped service worker registration, and gated proof access.</li>\n              <li>I pushed the repaired lane live at <code>https://sovereigndocs-0s-lane.pages.dev/Free99/apps/sovereigndocs/</code> and the main 0S mount now proxies that lane from <code>/Free99/apps/sovereigndocs/</code>.</li>\n            </ul>\n            <div class=\"receipt-row\"><span><a href=\"../Free99/apps/sovereigndocs/index.html\">SovereignDocs app</a></span><span><a href=\"../Free99/apps/sovereigndocs/official-sources/index.html\">Official prep workflows</a></span><span><a href=\"../Free99/apps/sovereigndocs/official-workflow-studio/index.html\">Prep studio</a></span><span>10,971 lane files</span><span>37 prep workflows</span><span>Live Playwright QA passed</span></div>\n          </div>\n        </article>\n\n        <article class=\"release-entry\" id=\"skysecure-fs27-vault-proof\">\n          <div class=\"release-meta\">\n            <time class=\"release-date\" datetime=\"2026-05-19\">May 19, 2026</time>\n            <span class=\"release-version\">SkySecure FS27 Vault Proof</span>\n          </div>\n          <div class=\"release-body\">\n            <div class=\"tag-row\"><span>SkySecure</span><span>FS27</span><span>SkyeVault</span><span>Secret packs</span><span>SkyeRunners</span><span>Public proof</span></div>\n            <h2>I published the encrypted secret-pack lane as live sovereign infrastructure.</h2>\n            <p>SkySecure now lives under SkyeVault, under FS27. The production proof encrypts the pack before vault handoff, keeps SkyeVault as ciphertext custody, stores hash-only metadata and grants through FS27, and exposes proof counts without publishing secret values.</p>\n            <ul class=\"release-points\">\n              <li>I shipped the public product page, local packer/unlocker console, platform console, and proof-vault receipt for the FS27 -> SkyeVault -> SkySecure chain.</li>\n              <li>I updated 0S public routing, Skyeway, sitemap, live-surface registry, SkyeRunners map, and the proof lane so operators and clients can inspect the same production story from multiple surfaces.</li>\n              <li>I refreshed the marketing kit so marketplace, proof, valuation, flyer, handout, sell sheet, no-competitor, and white-label pages now describe 24 platform lanes and the SkySecure proof-backed custody model.</li>\n              <li>I deployed the 0S Worker and both marketing Pages projects, then verified the public URLs instead of relying on local screenshots.</li>\n              <li>Live FS27 proof returned <code>ok=true</code>, hierarchy <code>FS27 -> SkyeVault -> SkySecure</code>, 3 packs, 3 active grants, and 9 events.</li>\n              <li>I kept the boundary explicit: public pages describe ciphertext custody, metadata-only registration, grants, and event proof, but no admin passwords, passphrases, write secrets, or secret file contents are published.</li>\n            </ul>\n            <div class=\"receipt-row\"><span><a href=\"../skye-secure-secret-packs.html\">Product page</a></span><span><a href=\"../skye-secure-secret-packs/app.html\">Local console</a></span><span><a href=\"../skye-secure-platform/index.html\">Platform console</a></span><span><a href=\"../proof-vault/skye-secure-fs27-vault-proof.html\">Proof receipt</a></span><span>0S deploy ad3bce8f</span><span>3 packs / 3 grants / 9 events</span></div>\n          </div>\n        </article>\n\n        <article class=\"release-entry\" id=\"free99-platform-intake\">\n          <div class=\"release-meta\">\n            <time class=\"release-date\" datetime=\"2026-05-18\">May 18, 2026</time>\n            <span class=\"release-version\">Free99/Paid-Apps Intake</span>\n          </div>\n          <div class=\"release-body\">\n            <div class=\"tag-row\"><span>Free99 intake</span><span>SovereignDocs</span><span>Platform gate</span><span>platform_id</span><span>usage_lane</span><span>Stripe rebuild pending</span></div>\n            <h2>I mounted the Free99/Paid-Apps intake into the 0S gate.</h2>\n            <p>SkyeOpsConsole was the first no-charge app in this intake; Still2Vid Forge has now joined it as a Free99 lane. SovereignDocs and the other imported platform lanes remain mounted for gated review with paid, quote, bundle, or owner-approved usage rules until the final Stripe/SKU rebuild is done.</p>\n            <ul class=\"release-points\">\n              <li>I mounted 11 imported apps under <code>Free99/apps</code> with the shared 0S/FS27 gate wrapper, platform_id tagging, and usage_lane boundaries.</li>\n              <li>I integrated SovereignDocs as a real app route, including its 10,200-record documents library through scoped app paths instead of leaving it as loose docs in the repo.</li>\n              <li>I added browser proof for the hub, app entrypoints, 275 non-generated mounted HTML routes, public discovery listings, and the SovereignDocs library render.</li>\n              <li>I kept checkout honest: paid apps are visible and gated, but they do not pretend to have final Stripe products until owner approval and the catalog rebuild assign the exact SKUs and rate limits.</li>\n            </ul>\n            <div class=\"receipt-row\"><span><a href=\"../Free99/index.html\">Intake hub</a></span><span><a href=\"../proof/free99-platform-intake-receipt.html\">Proof receipt</a></span><span><a href=\"../Free99/apps/sovereigndocs/documents/index.html\">SovereignDocs library</a></span><span>12 apps mounted</span><span>SkyeOpsConsole + Still2Vid Free99</span><span>275 HTML routes proved</span></div>\n          </div>\n        </article>\n\n        <article class=\"release-entry\">\n          <div class=\"release-meta\">\n            <time class=\"release-date\" datetime=\"2026-05-18\">May 18, 2026</time>\n            <span class=\"release-version\">Marketing Made Easy Gate Scan</span>\n          </div>\n          <div class=\"release-body\">\n            <div class=\"tag-row\"><span>Marketing Made Easy</span><span>Deep scan</span><span>FS27 Gate</span><span>0S registry</span><span>Quote-only</span><span>Execution proof</span></div>\n            <h2>I wired Marketing Made Easy into the 0S without overstating production.</h2>\n            <p>Marketing Made Easy is now accounted for as a routed growth-suite lane covering AE-FlowPro, BrandID Offline PWA, BusinessLaunchGo, SkyeDocxMax, SkyeWebCreatorMax, WebGrowthOperator, Arizona Growth Index, and kAIxU BrandKit. The suite has a public 0S hub, suite index, proof receipt, FS27 dossier, registry entries, and command-line proof lane.</p>\n            <ul class=\"release-points\">\n              <li>I deep-scanned <code>Marketing-Made-Easy/</code>, generated the local scan summary, added the scan/smoke/proof commands, and repaired stale smoke contracts after the routed-shell migration.</li>\n              <li>I added the suite to the 0S live-surface registry, sales-offer registry, platform integration ledger, SkyePay quote-only routing, FS27 runtime map, admin platform catalog, Gate map, proof center, home, feature atlas, operator, live router, sitemap, README, and LLM context.</li>\n              <li>I kept the boundary visible: this lane is gated and quote-only. It does not claim live checkout, customer tenancy, external publishing, ad spend, provider writes, or production deploy completion until owner approval and provider proof exist.</li>\n              <li>Local closeout passed with <code>npm run 0s:marketing-made-easy:proof</code>, <code>npm run 0s:platform-accounting</code>, browser proof on the three new routes, and <code>wrangler deploy --dry-run</code>. The live Worker deploy is still pending Cloudflare authentication.</li>\n            </ul>\n            <div class=\"receipt-row\"><span><a href=\"../live/marketing-made-easy-growth-suite.html\">0S hub</a></span><span><a href=\"../Marketing-Made-Easy/index.html\">Suite index</a></span><span><a href=\"../proof/marketing-made-easy-deep-scan-receipt.html\">Proof receipt</a></span><span>462 files scanned</span><span>8 apps accounted</span><span>Deploy auth pending</span></div>\n          </div>\n        </article>\n\n        <article class=\"release-entry\">\n          <div class=\"release-meta\">\n            <time class=\"release-date\" datetime=\"2026-05-18\">May 18, 2026</time>\n            <span class=\"release-version\">SkyeRunners Control Lane</span>\n          </div>\n          <div class=\"release-body\">\n            <div class=\"tag-row\"><span>SkyeRunners</span><span>Repo map</span><span>Human-flow QA</span><span>Local bridge</span><span>Stress proof</span><span>Approval gated</span></div>\n            <h2>I added SkyeRunners so the repo can test itself before customers find breakage.</h2>\n            <p>SkyeRunners is now the repo-aware worker-control lane for MetrAIyux 0S. It maps the codebase, feeds the local brain, refreshes Obsidian and SkyeVault memory, queues runner work, and runs human-flow QA through live system proof lanes with explicit execution scopes. It is local-only by default and does not bypass operator approval for spend, production deploys, credentials, billing, legal, hiring, payments, or customer-impacting actions.</p>\n            <ul class=\"release-points\">\n              <li>I added the SkyeRunners bridge, admin control page, generated brain map, queue/ledger lane, Obsidian note, operator guide, and tracked stress receipt.</li>\n              <li>I refreshed the knowledge chain so the local brain now loads the SkyeRunners repo map alongside Obsidian sync, live surfaces, persona brains, sales offers, legal sync, marketplace sync, and SkyeVault memory.</li>\n              <li>I stress-tested the lane locally: 286 bridge/browser/queue operations with 0 failures, 40 queue writes cleaned back to 0, and static SkyeCrawler proof across 647 HTML pages and 874 local references with 14 checks, 0 failures, and 0 warnings.</li>\n            </ul>\n            <div class=\"receipt-row\"><span><a href=\"../admin/skyerunners.html\">SkyeRunners admin</a></span><span><a href=\"../brain/skyerunners.json\">Brain map</a></span><span>286 stress ops</span><span>647 HTML pages</span><span>874 refs checked</span><span>0 failures</span></div>\n          </div>\n        </article>\n\n        <article class=\"release-entry\">\n          <div class=\"release-meta\">\n            <time class=\"release-date\" datetime=\"2026-05-18\">May 18, 2026</time>\n            <span class=\"release-version\">Transparent Split Engine Logos</span>\n          </div>\n          <div class=\"release-body\">\n            <div class=\"tag-row\"><span>Skye Split Engine</span><span>Transparent Logos</span><span>PWA Icons</span><span>Free99 Gate</span><span>Visual Polish</span></div>\n            <h2>I cut the Split Engine logos clean so they float without a baked-in plate.</h2>\n            <p>The Skye Split Engine import now uses transparent display logos across the app, hub, receipt, favicon, and PWA icon set while preserving the Free99 gate-session boundary. The original approved art stays in the folder as source, and the transparent variants are the live display assets.</p>\n            <ul class=\"release-points\">\n              <li>I added <code>skye-split-engine-logo-transparent.png</code> and <code>skye-split-badge-transparent.png</code> for live display surfaces.</li>\n              <li>I regenerated the favicon and app icon sizes from the transparent badge so browser/PWA surfaces stop carrying an opaque logo box.</li>\n              <li>I updated the app, hub, receipt, visual notes, smoke proof, and service-worker cache to use the transparent assets without changing the gate requirement.</li>\n            </ul>\n            <div class=\"receipt-row\"><span>Transparent assets</span><span>Icons regenerated</span><span>Cache bumped</span><span>Gate retained</span><span>Changelog updated</span></div>\n          </div>\n        </article>\n\n        <article class=\"release-entry\">\n          <div class=\"release-meta\">\n            <time class=\"release-date\" datetime=\"2026-05-17\">May 17, 2026</time>\n            <span class=\"release-version\">Feature Atlas Catch-Up</span>\n          </div>\n          <div class=\"release-body\">\n            <div class=\"tag-row\"><span>Feature atlas</span><span>Full inventory</span><span>Valuation</span><span>Payment surface</span><span>Claims ledger</span></div>\n            <h2>I surfaced the full 0S inventory as a live buyer route.</h2>\n            <p>This is catch-up accounting from the 2026-05-17 repo scan, not invented historical hash work. The new atlas links the full feature inventory, valuation desk, SkyePay surface, public claims ledger, proof routes, and app lanes so the system is no longer undersold as a handful of pages or one checkout path.</p>\n            <ul class=\"release-points\">\n              <li>I added <code>feature-atlas.html</code> as the live feature surface for 875 scanned HTML surfaces, 468 JS/MJS files, 465 Markdown docs, 1493 JSON files, 39 live production surfaces, and 58 Stripe catalog products.</li>\n              <li>I linked the atlas from the 0S home, valuation surface, SkyePay surface, FS27 SkyePay gateway/store, and the public marketing overview/capabilities/sell-sheet/valuation pages.</li>\n              <li>I kept the boundary visible: Free99 means no charge, not no-gate; payment, hiring, legal, public claims, and workspace activation stay approval-gated.</li>\n            </ul>\n            <div class=\"receipt-row\"><span><a href=\"../feature-atlas.html\">Feature atlas</a></span><span><a href=\"../FEATURE_INVENTORY.md\">Full inventory</a></span><span><a href=\"../docs/PUBLIC_CLAIMS_LEDGER.md\">Claims ledger</a></span><span>No fake hashes</span></div>\n          </div>\n        </article>\n\n        <article class=\"release-entry\">\n          <div class=\"release-meta\">\n            <time class=\"release-date\" datetime=\"2026-05-17\">May 17, 2026</time>\n            <span class=\"release-version\">App Lane Accounting</span>\n          </div>\n          <div class=\"release-body\">\n            <div class=\"tag-row\"><span>ConnectLog</span><span>HouseOps</span><span>RouteX</span><span>Media</span><span>Music</span><span>SkyeMail</span><span>CitadelDB</span></div>\n            <h2>I added the already-built app rooms to the public feature story.</h2>\n            <p>The catch-up pass records the deployed and repo-present lanes as part of the 0S product surface: ConnectLog + Relay13, HouseOperations + SkyeBox, SkyeRouteX, SkyeProfitConsole, SkyeMediaCenter, SkyeMusicNexus, Skye Content Forge, Skye Split Engine, SkyeMail, CitadelDB, and SOL Staffing.</p>\n            <ul class=\"release-points\">\n              <li>I turned those rooms into atlas cards with links back to their live surfaces, receipts, or execution-scope runbook files.</li>\n              <li>I kept payment and access language precise: free lanes remain no-charge gated lanes; paid lanes route through SkyePay, FS27 policy, and owner approval.</li>\n              <li>I connected sales, proof, payment, valuation, governance, and claims surfaces so buyers can follow the feature story without needing repo knowledge.</li>\n            </ul>\n            <div class=\"receipt-row\"><span>App lanes surfaced</span><span>Proof links attached</span><span>Gate boundary retained</span><span>Sales copy upgraded</span></div>\n          </div>\n        </article>\n\n        <article class=\"release-entry\">\n          <div class=\"release-meta\">\n            <time class=\"release-date\" datetime=\"2026-05-17\">May 17, 2026</time>\n            <span class=\"release-version\">Sales Copy Upgrade</span>\n          </div>\n          <div class=\"release-body\">\n            <div class=\"tag-row\"><span>Marketing</span><span>Sell sheet</span><span>Capabilities</span><span>Payment disclosure</span><span>Valuation disclosure</span></div>\n            <h2>I upgraded the sales copy so it stops making the platform look smaller than it is.</h2>\n            <p>The public marketing overview, full capabilities page, sell sheet, valuation route, 0S payment surface, and FS27 payment surfaces now link back to the live feature atlas. The buyer can inspect what the system does before checkout, diligence, or valuation review.</p>\n            <ul class=\"release-points\">\n              <li>I added feature-atlas CTAs to valuation and payment surfaces so buyers know what they are getting and what remains owner-approved.</li>\n              <li>I replaced older narrow copy with broader platform language covering app lanes, SkyeMail, CitadelDB, SkyeBox, SkyePay activation, and proof rooms.</li>\n              <li>I left dates honest: this is a May 17, 2026 documentation catch-up from the current repo state, not a reconstruction of older commit history.</li>\n            </ul>\n            <div class=\"receipt-row\"><span>Valuation linked</span><span>Payment linked</span><span>Marketing linked</span><span>Feature list visible</span></div>\n          </div>\n        </article>\n\n        <article class=\"release-entry\">\n          <div class=\"release-meta\">\n            <time class=\"release-date\" datetime=\"2026-05-17\">May 17, 2026</time>\n            <span class=\"release-version\">Skye Split Engine Free99</span>\n          </div>\n          <div class=\"release-body\">\n            <div class=\"tag-row\"><span>Skye Split Engine</span><span>Free99</span><span>Gate Session</span><span>Price Card</span><span>Browser Proof</span></div>\n            <h2>I imported Skye Split Engine as a no-charge split and payout command app.</h2>\n            <p>Skye Split Engine is now part of the 0S as Free99, meaning no charge. It still requires a gate session before app boot, and it stays honest about its boundary: split rules, transactions, reports, exports, backups, and repair controls, not live money movement or accounting/legal replacement.</p>\n            <ul class=\"release-points\">\n              <li>I unpacked the archive into <code>metraiyux_0s_site/SkyeSplitEngine</code> and removed the source zip.</li>\n              <li>I added a gate-session helper so 0S, FS27, SkyGate, or local admin session proof is required before the app renders.</li>\n              <li>I wired the Free99 price card, SaaS routes, proof routes, sales router, admin/operator links, registries, README, LLM context, and catalog guardrails.</li>\n            </ul>\n            <div class=\"receipt-row\"><span>Free99 no charge</span><span>Gate required</span><span>Zip removed</span><span>Price card updated</span><span>Browser proof</span><span>No auth bypass</span></div>\n          </div>\n        </article>\n\n        <article class=\"release-entry\">\n          <div class=\"release-meta\">\n            <time class=\"release-date\" datetime=\"2026-05-17\">May 17, 2026</time>\n            <span class=\"release-version\">SkyeVault/R2 Storage Cutover</span>\n          </div>\n          <div class=\"release-body\">\n            <div class=\"tag-row\"><span>Skye Content Forge</span><span>SkyeVault/R2</span><span>Google infra replaced</span><span>Root env</span><span>Gate required</span><span>Free99</span></div>\n            <h2>I replaced the Content Forge cloud storage lane with my own SkyeVault/R2 infrastructure.</h2>\n            <p>Skye Content Forge no longer depends on Google Drive as the primary cloud export path. The platform now writes generated Markdown into the live SkyeVault Cloudflare R2 bucket while keeping Free99 as no charge and keeping every API/export path behind a gate session.</p>\n            <ul class=\"release-points\">\n              <li>I changed the app health, export panel, publisher target, docs, setup notes, hub, proof receipt, manifest, and 0S homepage copy from Google Drive-primary language to SkyeVault/R2-primary language.</li>\n              <li>I wired <code>/api/export/skyevault-r2</code> through the existing SkyeVault-Drop R2 adapter and normalized root env aliases for <code>CLOUDFLARE_R2_ACCOUNT_ID</code>, <code>CLOUDFLARE_R2_ACCESS_KEY</code>, <code>CLOUDFLARE_R2_SECRET_KEY</code>, and <code>S3_BUCKET</code>.</li>\n              <li>I verified the live R2 route by writing Markdown into bucket <code>client-drop-vault</code> under <code>content-forge-exports</code> and receiving a signed download URL back from the app.</li>\n              <li>I verified scheduled publishing through target <code>skyevault-r2</code>; scheduled item <code>439246bc-6c0a-4cb1-b4eb-e71d02c0085d</code> published into SkyeVault/R2 instead of a Google-owned folder.</li>\n              <li>I kept Google Drive as an optional legacy path only. The current Google service-account target is auth-valid but storage-owner blocked by normal My Drive rules unless a Shared Drive or delegated OAuth lane is used.</li>\n              <li>I proved the security boundary after the cutover: unauthenticated API health returns <code>401</code>, authenticated health returns <code>200</code>, and the browser dashboard shows <code>AI ready</code>, <code>Vault/R2 configured</code>, and <code>Upload to SkyeVault/R2</code>.</li>\n            </ul>\n            <div class=\"receipt-row\"><span>Google infra replaced</span><span>SkyeVault/R2 primary</span><span>R2 route 200</span><span>Unauth 401</span><span>Publisher target proven</span><span>Free99 gated</span></div>\n          </div>\n        </article>\n\n        <article class=\"release-entry\">\n          <div class=\"release-meta\">\n            <time class=\"release-date\" datetime=\"2026-05-17\">May 17, 2026</time>\n            <span class=\"release-version\">HouseOperations Radical V3</span>\n          </div>\n          <div class=\"release-body\">\n            <div class=\"tag-row\"><span>HouseOperations</span><span>SkyeBox</span><span>MCP tooling</span><span>SkyePay</span><span>FS27 Gate</span><span>Browser proof</span></div>\n            <h2>I replaced the old HouseOperations shell with a real command-floor app surface.</h2>\n            <p>HouseOperations no longer presents as the same sidebar dashboard with polish on top. The current release opens as a cache-busted radical v3 command floor with top navigation, mission plates, a working operator intake dock, proof spine, billing console, tutorial deck, SkyeBox vault runway, and FS27 PIN Gate handoff.</p>\n            <ul class=\"release-points\">\n              <li>I changed every HouseOperations page shell to <code>houseops-command-v3</code>, added <code>data-surface-version=\"houseops-radical-v3-20260517\"</code>, and cache-busted the CSS/JS links so the browser cannot silently show the old UI.</li>\n              <li>I rebuilt the dashboard first viewport around the actual app actions: New Task, New Vendor, Save Proof, Export, open work count, owner escalations, vendor value, and active monthly plan.</li>\n              <li>I redesigned the billing and tutorial surfaces so charge-ready intents, tutorial receipts, SkyePay offer URLs, and activation boundaries are visible as product work instead of buried panels.</li>\n              <li>I kept the app honest: HouseOperations records local state, proof, billing intent, and gate mirror packets; SkyePay and FS27 still own payment confirmation, owner approval, policy activation, PIN login, and recovery boundaries.</li>\n              <li>I used the repo MCP workflow before and after the redesign. The final MCP miner receipt returned <code>ok: true</code> with <code>failedCalls: []</code>, and the MCP effect/validate passes recognize the neon scrollbar, motion chrome, living background, text effect, surface screenshot, and real logo asset signals.</li>\n              <li>I reran the full proof set: <code>npm run 0s:houseops-skyebox:e2e</code>, <code>npm run 0s:houseops:claims</code>, <code>npm run 0s:houseops:skyepay</code>, and the SkyeBox static/TOTP crypto proof scripts all passed.</li>\n              <li>I verified desktop and mobile browser flows for HouseOperations and SkyeBox: task creation, state advance, proof save, backup export, tutorial receipt export, billing intent export, TOTP save, encrypted vault backup, endpoint JSON checks, video playback proof, and no horizontal scroll.</li>\n            </ul>\n            <div class=\"receipt-row\"><span>Radical v3 UI</span><span>Cache busted</span><span>MCP receipt clean</span><span>E2E clean</span><span>SkyeBox crypto clean</span><span>No horizontal scroll</span></div>\n          </div>\n        </article>\n\n        <article class=\"release-entry\">\n          <div class=\"release-meta\">\n            <time class=\"release-date\" datetime=\"2026-05-17\">May 17, 2026</time>\n            <span class=\"release-version\">Customer-Ready SkyeMerit + Media Center</span>\n          </div>\n          <div class=\"release-body\">\n            <div class=\"tag-row\"><span>Production deployed</span><span>SkyeMerit</span><span>SkyeMediaCenter</span><span>FS27 checkout</span><span>Gate required</span></div>\n            <h2>I closed the SkyeMerit and SkyeMediaCenter release for customer use.</h2>\n            <p>This closeout moves the new Free99 platform expansion from internal execution proof into the live Cloudflare customer path. Free99 means no charge; it does not mean anonymous access, and paid work still routes through SkyePay, FS27, and owner approval.</p>\n            <ul class=\"release-points\">\n              <li>I deployed the 0S full-system Worker, SaaS provisioning Worker, and FS27/SkyePay Worker with the new SkyeMerit, SkyeMediaCenter, pricing, and owner-approval changes live.</li>\n              <li>I changed customer checkout routing away from legacy <code>skyesol.netlify.app/skyepay</code> URLs and made the live FS27 Cloudflare Worker the active SkyePay checkout origin.</li>\n              <li>I proved the live SkyeMerit path end to end: catalog, preview math, no-auth issue rejection, signup pack issuance, D1 persistence, kAIxu credit, and gate-required pack state.</li>\n              <li>I added runtime self-repair for the <code>skyemerit_packs</code> D1 table so the live Worker can create the missing table through its bound database and keep issuing packs without a manual API migration blocker.</li>\n              <li>I verified SkyeMediaCenter as a real routed app surface with root, dashboard, records, workflows, runtime, settings, proof, public intake, and operator theater pages.</li>\n              <li>I confirmed paid MetrAIyux app lanes, including RouteX, remain owner-approved after payment instead of auto-unlocking from Stripe success.</li>\n            </ul>\n            <div class=\"receipt-row\"><span>0S Worker live</span><span>SaaS Worker live</span><span>FS27 Worker live</span><span>Checkout on Cloudflare</span><span>D1 persistence repaired</span><span>Live proof clean</span></div>\n          </div>\n        </article>\n\n        <article class=\"release-entry\">\n          <div class=\"release-meta\">\n            <time class=\"release-date\" datetime=\"2026-05-17\">May 17, 2026</time>\n            <span class=\"release-version\">Valley Publisher</span>\n          </div>\n          <div class=\"release-body\">\n            <div class=\"tag-row\"><span>Valley Verified</span><span>28 guides</span><span>Scheduled publishing</span><span>0S Worker</span><span>Scope rollback</span></div>\n            <h2>I turned Valley Verified into a scheduled company-running publication engine.</h2>\n            <p>Valley Verified now has a real operating-insights section instead of a single blog stub: longform guides teach practical company work first, then point owners into the major 0S and company platforms that make the repeated work easier.</p>\n            <ul class=\"release-points\">\n              <li>I added a 28-guide editorial library with 18 live guides, 10 scheduled guides, and 6 topic clusters covering weekly command rhythm, local visibility, intake, records, security, reviews, market research, pricing, proof, retention, delegation, cashflow, and customer status control.</li>\n              <li>I kept the backlinks focused on major live platforms only: MetrAIyux 0S, SkyeVault, SkyeGateFS27/SkyePay, Deployment Atlas, Skyes Over London Reviews, and SOLEnterprises.</li>\n              <li>I added the public insights hub at <code>/insights/</code>, category routes, the public schedule at <code>/insights/schedule/</code>, and the machine-readable calendar at <code>/api/insights-editorial-calendar.json</code>.</li>\n              <li>I wired the 0S Worker endpoint at <code>/api/valley/content-schedule</code> so the system can read the calendar, detect due guides, store receipts, and queue operator publish tasks.</li>\n              <li>I configured the Worker cron as <code>17 13 * * 1,3,5</code> and kept the manual tick route protected so scheduled publishing does not become an anonymous public button.</li>\n              <li>I verified production after deploy: the Valley publication engine browser QA returned 42 checks and zero failures.</li>\n              <li>I also rolled the unrelated portal/site-design deployment back to <code>c98babbd-7ea5-4151-8cea-65f79da6603f</code>; this changelog entry is scoped to the Valley blog and scheduler work only.</li>\n            </ul>\n            <div class=\"receipt-row\"><span>18 live guides</span><span>10 scheduled</span><span>6 clusters</span><span>Calendar JSON 200</span><span>Worker schedule API 200</span><span>42 QA checks clean</span></div>\n          </div>\n        </article>\n\n        <article class=\"release-entry\">\n          <div class=\"release-meta\">\n            <time class=\"release-date\" datetime=\"2026-05-17\">May 17, 2026</time>\n            <span class=\"release-version\">0S Expansion Accounted</span>\n          </div>\n          <div class=\"release-body\">\n            <div class=\"tag-row\"><span>SkyeMerit</span><span>RouteX unified</span><span>SkyeVault/R2</span><span>Proof router</span><span>Sales surfaces</span><span>Receipts</span></div>\n            <h2>I accounted for the new 0S platforms across proof, sales, pricing, and operator routing.</h2>\n            <p>This pass makes the expansion visible instead of just present in the repo: the changelog, proof routes, live proof router, surface registries, sales offer registry, README, public home routing, and SkyeVault/R2 storage posture now reflect the added lanes and their guardrails.</p>\n            <ul class=\"release-points\">\n              <li>I added SkyeMerit as a first-class no-charge customer merit lane: wallet, operator issue control, protected discount math, kAIxu credit, FS27 SkyePay support, and proof receipt.</li>\n              <li>I documented the RouteX folder unification so SkyeRouteX and Workforce Command v0.4.0 stay together under <code>SkyeRouteX/workforce-command-v0.4.0</code>, with the old top-level path kept only as a compatibility pointer.</li>\n              <li>I kept the advertising path honest: Free99 means no charge, not anonymous access; paid lanes still require SkyePay, FS27, owner approval, and gate sessions where applicable.</li>\n              <li>I updated buyer routing so sales can show SkyeMerit for first-time credits and capped discount questions, SkyeRouteX for field workforce operations, SkyeMusicNexus for music drops and rights-gated release work, SkyeMediaCenter for asset operations, Skye Content Forge for publishing, SkyeProfitConsole for margin decisions, HouseOperations + SkyeBox for task/vendor and authenticator custody, and ConnectLog + Relay13 for relationship and messaging infrastructure.</li>\n              <li>I recorded the proof commands for SkyeMerit, SkyeRouteX, SkyeMusicNexus, SkyeMediaCenter, HouseOperations + SkyeBox, Skye Content Forge, SkyeProfitConsole, ConnectLog, and Relay13 so the system has an audit path for each expansion instead of loose copy.</li>\n              <li>I added the Content Forge storage cutover to the release record because replacing Google cloud storage assumptions with the owned SkyeVault/R2 lane is infrastructure, not copy polish.</li>\n            </ul>\n            <div class=\"receipt-row\"><span>SkyeMerit receipt</span><span>Proof index updated</span><span>SkyeVault/R2 accounted</span><span>Sales router updated</span><span>Canonical RouteX path</span><span>No auth bypass claims</span></div>\n          </div>\n        </article>\n\n        <article class=\"release-entry\">\n          <div class=\"release-meta\">\n            <time class=\"release-date\" datetime=\"2026-05-17\">May 17, 2026</time>\n            <span class=\"release-version\">Music Nexus Studio Redesign</span>\n          </div>\n          <div class=\"release-body\">\n            <div class=\"tag-row\"><span>SkyeMusicNexus</span><span>Upload Studio</span><span>Drag/drop</span><span>Sitewide design</span><span>Browser proof</span></div>\n            <h2>I rebuilt the music surface around a real song drop target and calmer studio console design.</h2>\n            <p>The MusicNexus public app no longer leans on a cramped neon-dashboard feel. The Upload Studio now has a large song drop zone for audio files, selected-file state, title autofill, and the same gated upload path. The shared stylesheet now gives dashboard, upload, release, rights, exchange, player, and operator rooms a roomier studio-console rhythm.</p>\n            <ul class=\"release-points\">\n              <li>I replaced the small audio file field with a first-class <code>Drop songs here</code> zone that supports drag/drop and click-to-select.</li>\n              <li>I added browser runtime handling for dragenter, dragover, drop, rejected non-audio files, selected file labels, and track title autofill.</li>\n              <li>I refreshed the MusicNexus design system with tighter panels, calmer color, clearer room grids, larger workflow targets, and less bunched dashboard composition.</li>\n              <li>I extended smoke and browser proof to assert the new drop zone is visible and large enough on desktop.</li>\n            </ul>\n            <div class=\"receipt-row\"><span>Drop zone added</span><span>Drag/drop wired</span><span>Studio console skin</span><span>Smoke covered</span><span>E2E covered</span></div>\n          </div>\n        </article>\n\n        <article class=\"release-entry\">\n          <div class=\"release-meta\">\n            <time class=\"release-date\" datetime=\"2026-05-17\">May 17, 2026</time>\n            <span class=\"release-version\">Music Nexus Identity Bridge</span>\n          </div>\n          <div class=\"release-body\">\n            <div class=\"tag-row\"><span>SkyeMusicNexus</span><span>Skye-ID</span><span>Artist photos</span><span>Cross-app identity</span><span>SkyGate</span></div>\n            <h2>I wired artist identity so the Skye ID and photo can follow the artist across app rooms.</h2>\n            <p>The Skye-ID generator now publishes a shared 0S identity draft with the artist ID and profile photo. MusicNexus reads that identity in the gated artist registration flow, uses the Skye ID as the artist node when available, persists the profile photo on the artist record, and fills artist ID fields across the upload, release, exchange, and operations rooms.</p>\n            <ul class=\"release-points\">\n              <li>I added the shared <code>skye0s.identity.current.v1</code> browser bridge while preserving the legacy <code>kx.onboarding.idDraft</code> key.</li>\n              <li>I upgraded both Skye-ID generator copies to publish the artist photo, Skye ID, identity ID, and cross-app update event.</li>\n              <li>I updated MusicNexus artist registration so profile photos and Skye IDs are stored behind SkyGate instead of floating as public form data.</li>\n              <li>I extended the smoke proof so the handler registers an artist with a Skye ID, persists a photo, and can retrieve the artist by that Skye ID.</li>\n            </ul>\n            <div class=\"receipt-row\"><span>Skye ID shared</span><span>Photo handoff</span><span>Artist ID populated</span><span>Gate required</span><span>Smoke covered</span></div>\n          </div>\n        </article>\n\n        <article class=\"release-entry\">\n          <div class=\"release-meta\">\n            <time class=\"release-date\" datetime=\"2026-05-17\">May 17, 2026</time>\n            <span class=\"release-version\">Music Nexus Full Platform</span>\n          </div>\n          <div class=\"release-body\">\n            <div class=\"tag-row\"><span>SkyeMusicNexus</span><span>Upload Studio</span><span>Music Player</span><span>SkyGate</span><span>SkyeVault Path</span></div>\n            <h2>I split SkyeMusicNexus into a real gated platform with upload and player rooms.</h2>\n            <p>The music app is no longer bunched into one artist page. It now opens as platform rooms for dashboard, upload, player, releases, rights, exchange, and operator review, with audio upload/list/stream actions protected by the same gate session boundary.</p>\n            <ul class=\"release-points\">\n              <li>I added a dedicated Upload Studio with a real file input, base64 audio handoff, generated release track lines, and an uploaded audio vault.</li>\n              <li>I added <code>music-assets.js</code> so audio upload, list, stream, and delete actions require SkyGate before any file movement, with operator proof storage by default and an opt-in SkyeVault/R2 backend for durable audio objects.</li>\n              <li>I wired future production switches for direct R2 upload sessions, upload completion, and provider jobs for transcoding, waveform/CDN, DSP, legal review, and royalty settlement without turning those providers on prematurely.</li>\n              <li>I updated the Music Player so uploaded audio stream URLs are fetched through authenticated SkyGate fetch and played as object URLs instead of becoming public direct links.</li>\n              <li>I split the public app into <code>dashboard</code>, <code>upload</code>, <code>player</code>, <code>releases</code>, <code>rights</code>, and <code>exchange</code> rooms, then updated the root shell to launch those rooms directly.</li>\n              <li>I updated the rate card so Free99 Lite remains no charge but only gets a tiny proof upload, while serious upload/storage work has the paid Gated Audio Vault Pack and the SkyeVault/R2 upgrade path.</li>\n              <li>I kept the legal boundary honest: this proves gated upload and proof playback, not public streaming licensing, DSP ingestion, transcoding/CDN delivery, or provider catalog operations until those integrations are connected and tested.</li>\n            </ul>\n            <div class=\"receipt-row\"><span>Roomed platform</span><span>Gated upload</span><span>Player fetch auth</span><span>Audio vault add-on</span><span>SkyeVault/R2 path</span><span>No auth bypass</span></div>\n          </div>\n        </article>\n\n        <article class=\"release-entry\">\n          <div class=\"release-meta\">\n            <time class=\"release-date\" datetime=\"2026-05-17\">May 17, 2026</time>\n            <span class=\"release-version\">Client Chat Lanes</span>\n          </div>\n          <div class=\"release-body\">\n            <div class=\"tag-row\"><span>Relay13</span><span>Bob's Smoke Shop</span><span>Empire Pallets</span><span>Workspace Chat</span><span>Password Gate</span></div>\n            <h2>I made the client app chat lanes real for Bob and Empire Pallets.</h2>\n            <p>Bob's Smoke Shop and Empire Pallets now have live, account-tied workspace chat widgets in their public apps. Relay13 auto-provisions both workspaces, validates the app origins, and accepts live conversation posts from the deployed client sites.</p>\n            <ul class=\"release-points\">\n              <li>I installed the reusable workspace chat widget as an MCP pattern and mounted it in Bob's app, Bob's private workspace page, and the Empire Pallets app.</li>\n              <li>I deployed Relay13 with known-client widget provisioning for <code>bobs-smoke-shop</code> and <code>empire-pallets</code>, including app-origin CORS and workspace domain checks.</li>\n              <li>I deployed the updated Bob and Empire Cloudflare Pages projects so the live apps serve <code>/assets/workspace-chat-widget.js</code>.</li>\n              <li>I delivered Bob's workspace popup password into his live Relay13 workspace inbox as a dedicated handoff thread.</li>\n              <li>I verified live browser chat from <code>bobs-smoke-shop.pages.dev</code> and <code>empire-pallets.pages.dev</code>; both sent messages into Relay13 and returned live workspace-lane confirmations.</li>\n            </ul>\n            <div class=\"receipt-row\"><span>Relay13 version 7bb9eb26</span><span>Bob inbox conv_ed59c64a</span><span>Bob proof conv_af22ca71</span><span>Empire proof conv_e585eeb1</span><span>4 app targets deployed</span><span>Widget assets 200</span></div>\n          </div>\n        </article>\n\n        <article class=\"release-entry\">\n          <div class=\"release-meta\">\n            <time class=\"release-date\" datetime=\"2026-05-17\">May 17, 2026</time>\n            <span class=\"release-version\">RouteX Live Gate</span>\n          </div>\n          <div class=\"release-body\">\n            <div class=\"tag-row\"><span>SkyeRouteX</span><span>SkyePay</span><span>Owner Approval</span><span>Root Env</span><span>Live Ops</span></div>\n            <h2>I brought SkyeRouteX into the 0S as a paid, gated client-use platform.</h2>\n            <p>SkyeRouteX Workforce Command is now wired into the 0S expansion surface, SkyePay checkout, owner-approval queue, live route intelligence, and production proof path. The app can take client payment into a controlled paid queue while keeping workspace activation behind owner approval.</p>\n            <ul class=\"release-points\">\n              <li>I added the RouteX offer to SkyePay at $6,500 setup plus $1,497 per month, with lookup keys for setup and monthly Stripe prices.</li>\n              <li>I changed the paid app activation path so RouteX and core app lanes do not auto-unlock after payment; paid orders enter pending owner approval first.</li>\n              <li>I updated SkyePay checkout, status, store copy, API docs, admin ledger policy, and browser scanner expectations to show pending owner approval honestly.</li>\n              <li>I wired the root production env bridge to use existing repo aliases for Neon/Postgres, Cloudflare R2, Stripe, Twilio, compliance webhooks, the 0S runtime, and the root <code>mapbox_api_key</code> alias for Mapbox route intelligence.</li>\n              <li>I fixed the live env proof so it now reports <code>PASS</code>, <code>customer_ready_for_paid_owner_approval_queue: true</code>, <code>customer_ready_for_full_live_route_ops: true</code>, and zero warnings.</li>\n              <li>I stress tested RouteX with 608 requests and no 500s; expected assignment lock conflicts stayed controlled as 409s.</li>\n              <li>I reran the 0S RouteX proof, SkyePay owner-approval regression, SkyePay browser proof, SkyePay crawler, deploy readiness smoke, provider webhook smoke, and MCP tooling receipts.</li>\n            </ul>\n            <div class=\"receipt-row\"><span>Live env PASS</span><span>Mapbox alias wired</span><span>R2 proof storage wired</span><span>Owner approval required</span><span>608 stress requests</span><span>0 warnings</span></div>\n          </div>\n        </article>\n\n        <article class=\"release-entry\">\n          <div class=\"release-meta\">\n            <time class=\"release-date\" datetime=\"2026-05-17\">May 17, 2026</time>\n            <span class=\"release-version\">Free99+ Link Proof</span>\n          </div>\n          <div class=\"release-body\">\n            <div class=\"tag-row\"><span>SkyeProfitConsole</span><span>Free99</span><span>Money Moves</span><span>Gate Session</span><span>Link Proof</span></div>\n            <h2>I turned SkyeProfitConsole Free99 into a gated close desk and proved the links.</h2>\n            <p>I keep SkyeProfitConsole Free99, meaning no charge, while making it feel worth paying attention to: Money Moves rank cash-now lanes, close briefs package the ask, and the runtime archives the brief behind the same 0S/FS27 gate. Free99 does not mean no-auth.</p>\n            <ul class=\"release-points\">\n              <li>I added the Money Moves panel across every SkyeProfitConsole route with fastest-cash ranking, ready/approved cash-now value, blocked-margin detection, selected-pack payback, and next-action scoring.</li>\n              <li>I added close brief generation so a selected profit pack can produce the ask, owner, deadline, expected profit, margin, payback, risk flags, split allocation, and runtime archive event.</li>\n              <li>I expanded the local runtime with gated close-brief storage, board counts, workflow timeline events, and a host override so the app can answer from the forwarded Codespaces link instead of only loopback.</li>\n              <li>I updated the price cards, SaaS surfaces, hub, receipt, operator route, README, and LLM context so SkyeProfitConsole is clearly Free99 and no charge while still presented as a higher-value platform feature.</li>\n              <li>I verified the auth boundary after the link fix: app shell returns 200, ungated runtime status returns 401, gated runtime status returns 200, and close brief archive proof stays behind the gate.</li>\n              <li>I reran proof after the final runtime fix: platform smoke and E2E passed, the MCP receipt returned zero failed calls, the commercial limits audit passed, and the static crawler checked 623 HTML files, 759 linked refs, desktop/mobile sweeps, 14 checks, zero failures, and zero warnings.</li>\n            </ul>\n            <div class=\"receipt-row\"><span>Free99 no charge</span><span>Gate required</span><span>Links 200</span><span>Runtime 401/200</span><span>Close briefs</span><span>623 pages clean</span></div>\n          </div>\n        </article>\n\n        <article class=\"release-entry\">\n          <div class=\"release-meta\">\n            <time class=\"release-date\" datetime=\"2026-05-17\">May 17, 2026</time>\n            <span class=\"release-version\">0S + Relay13</span>\n          </div>\n          <div class=\"release-body\">\n            <div class=\"tag-row\"><span>ConnectLog</span><span>Relay13</span><span>FS27 Gate</span><span>Production Proof</span></div>\n            <h2>I hardened the public 0S story around the production relationship infrastructure.</h2>\n            <p>ConnectLog, Relay13, FS27, and the 0S proof surfaces now present the system as production infrastructure: Worker, D1, scoped keys, activation proof, message history, WebSocket proof, gate routing, and ledgered deployment evidence.</p>\n            <ul class=\"release-points\">\n              <li>I removed weak public framing from the 0S home, ConnectLog app, ConnectLog landing, operator hub, proof receipt, proof center, Cabinet Brain, live-surface registry, and FS27 gate lane.</li>\n              <li>I redeployed the 0S hardening release and recorded the deployment and version IDs in the production ledger.</li>\n              <li>I redeployed the FS27 gate lane and recorded the deployment and version IDs in the production ledger.</li>\n              <li>Live browser proof passed on desktop and mobile for the 0S home, ConnectLog app, landing, hub, receipt, proof center, Cabinet Brain, FS27 gate lane, and live-surface registry.</li>\n              <li>The strict request pass hit 120 live reads across 0S, Relay13 health, ConnectLog bridge health, and FS27 with zero failures.</li>\n              <li>The CEO ledger, vault deployment ledger, and Live Surface Registry now point to the final deployment IDs and proof artifact.</li>\n            </ul>\n            <div class=\"receipt-row\"><span>0S deploy 795461c3</span><span>FS27 deploy cbcf8b54</span><span>Relay13 Worker</span><span>D1 proof</span><span>120 live reads</span><span>Zero failures</span></div>\n          </div>\n        </article>\n\n        <article class=\"release-entry\">\n          <div class=\"release-meta\">\n            <time class=\"release-date\" datetime=\"2026-05-17\">May 17, 2026</time>\n            <span class=\"release-version\">Valley Verified</span>\n          </div>\n          <div class=\"release-body\">\n            <div class=\"tag-row\"><span>Valley Verified</span><span>Client Builds</span><span>Share Rails</span><span>Browser Proof</span></div>\n            <h2>I shipped Valley Verified as a no-obligation visibility gift with real client build proof.</h2>\n            <p>Valley Verified now sells itself through the workflow: customers can receive a free public business page after their first paid month, and optional upgrades stay positioned as extra reach only when the owner wants them.</p>\n            <ul class=\"release-points\">\n              <li>I renamed and deployed the Valley Verified network with the new logo, pulse/float/glow treatment, living background, text effects, and clean public copy.</li>\n              <li>I made Bob's Smoke Shop and Empire Pallets featured businesses with dedicated Valley pages that link into their live apps, while the live apps link back to their Valley Verified posts.</li>\n              <li>I added share paths for Email, Text, LinkedIn, Facebook, X, native share, and copy-link flows across Valley pages, Bob, Empire, and the 0S client-build sections.</li>\n              <li>I added the Request a Build and live client builds sections with actual Bob and Empire video previews so prospects can see the free public page path and the full app path side by side.</li>\n              <li>I wired the 0S marketplace fit-check/brain section to explain which offer fits the buyer, route people to links, and keep Valley Verified described as a gift with no obligation to upgrade.</li>\n              <li>Production browser proof returned HTTP 200 for the Valley home, Bob featured page, Empire featured page, long-tail business fallback, Bob after age gate, Empire, 0S home, and 0S marketplace.</li>\n            </ul>\n            <div class=\"receipt-row\"><span>Clean Pages URLs</span><span>Two-way backlinks</span><span>Share actions</span><span>Client videos</span><span>Tooling receipts</span><span>Browser QA</span></div>\n          </div>\n        </article>\n\n        <article class=\"release-entry\">\n          <div class=\"release-meta\">\n            <time class=\"release-date\" datetime=\"2026-05-17\">May 17, 2026</time>\n            <span class=\"release-version\">Music Rights Gate</span>\n          </div>\n          <div class=\"release-body\">\n            <div class=\"tag-row\"><span>SkyeMusicNexus</span><span>Rights Vault</span><span>Takedown Hold</span><span>Legal-Safe Controls</span></div>\n            <h2>I added the rights gate so MusicNexus can grow without pretending every song is cleared.</h2>\n            <p>SkyeMusicNexus now treats playback and release movement as rights-gated product actions: artists can still use the exchange, content, progress, and generated proof lanes, but linked audio and release distribution controls need attestation first.</p>\n            <ul class=\"release-points\">\n              <li>I added a Rights Vault for ownership, preview-use, distribution, sample, cover, publisher, takedown contact, and notes attestation.</li>\n              <li>I added a Takedown Hold path that blocks playback and keeps the request in the release rights audit trail.</li>\n              <li>I made linked preview playback reject until ownership and preview-use rights are saved.</li>\n              <li>I made release publish, stream reporting, and operations queueing reject until the distribution rights gate is ready.</li>\n              <li>I kept the legal boundary honest: this proves product controls, not formal legal advice, registered DMCA-agent operations, live catalog licensing, or Spotify-scale streaming.</li>\n            </ul>\n            <div class=\"receipt-row\"><span>Rights Vault</span><span>Takedown hold</span><span>Publish gate</span><span>Stream gate</span><span>Ops gate</span><span>Smoke proof</span></div>\n          </div>\n        </article>\n\n        <article class=\"release-entry\">\n          <div class=\"release-meta\">\n            <time class=\"release-date\" datetime=\"2026-05-17\">May 17, 2026</time>\n            <span class=\"release-version\">Artist Exchange + Add-ons</span>\n          </div>\n          <div class=\"release-body\">\n            <div class=\"tag-row\"><span>SkyeMusicNexus</span><span>Artist Exchange</span><span>Content Add-ons</span><span>Gate Session</span></div>\n            <h2>I expanded SkyeMusicNexus into a gated artist exchange with content requests, inbox threads, community signals, and achievements.</h2>\n            <p>I route SkyeMusicNexus through the 0S as a gated music platform: Lite stays Free99, while Studio, Label Command, Managed Music Ops, Single Song Drop, release drops, content kits, campaign sprints, catalog import, ledger setup, payout review, artist profile, and capacity add-ons are paid.</p>\n            <ul class=\"release-points\">\n              <li>I added SkyeMusicNexus to the 0S as a new gated music platform surface and cleared the import archive after the app was in place.</li>\n              <li>I show Free99 only for SkyeMusicNexus Lite across the hub, pricing cards, SaaS selector, admin/operator routes, sales router, SkyePay route data, brain registries, sitemap, README, and llms context.</li>\n              <li>I added paid upgrade paths and add-ons, including a $199 Single Song Drop for buyers who only need one song handled.</li>\n              <li>I added the gated music exchange: content request work packets, ConnectLog + Relay13-ready inbox threads, community posts, release campaign packs, and achievement progression.</li>\n              <li>I added new content add-ons: Social Caption Pack, Cover / Canvas Request, Short-Form Clip Brief, Release Content Kit, and Community Campaign Sprint.</li>\n              <li>I keep the app shell, Artist Stage, Operator Stage, artist records, release lists, operations board, analytics, payouts, exchange hub, content requests, inbox, community posts, and workflow proof behind a 0S, FS27, or SkyGate session.</li>\n              <li>We verified ungated artist/release/workflow/exchange reads return 401, seeded gate sessions unlock the app, and desktop/mobile browser routes render without horizontal overflow.</li>\n            </ul>\n            <div class=\"receipt-row\"><span>Artist exchange</span><span>Content add-ons</span><span>Gate required</span><span>401 proof</span><span>Tooling receipt</span></div>\n          </div>\n        </article>\n\n        <article class=\"release-entry\">\n          <div class=\"release-meta\">\n            <time class=\"release-date\" datetime=\"2026-05-17\">May 17, 2026</time>\n            <span class=\"release-version\">61</span>\n          </div>\n          <div class=\"release-body\">\n            <div class=\"tag-row\"><span>SkyePay</span><span>Stripe</span><span>Gateway</span></div>\n            <h2><span class=\"magic-highlighter\" data-highlight=\"underline\" style=\"--highlighter-color:#FF9800;display:inline;box-decoration-break:clone;-webkit-box-decoration-break:clone;text-decoration-line:underline;text-decoration-color:var(--highlighter-color);text-decoration-thickness:.16em;text-underline-offset:.13em;text-decoration-skip-ink:none\">SkyeGateFS27</span> / SkyePay store deployed with live Stripe handoff.</h2>\n            <p>SkyePay production exposes Stripe-backed offers while the private tester lane stays clean and owner-controlled.</p>\n            <ul class=\"release-points\">\n              <li>61 Stripe-backed offers are exposed by the public store.</li>\n              <li>Live Stripe Checkout handoff was verified with a live checkout session.</li>\n              <li>Bob's private tester lane is simplified to a free tester-week handoff.</li>\n              <li>Owner approval and payment state stay inside the FS27 production flow.</li>\n            </ul>\n            <div class=\"receipt-row\"><span>Desktop proof</span><span>Mobile proof</span><span>Stripe screenshot</span><span>Proof JSON</span></div>\n          </div>\n        </article>\n\n        <article class=\"release-entry\">\n          <div class=\"release-meta\">\n            <time class=\"release-date\" datetime=\"2026-05-16\">May 16, 2026</time>\n            <span class=\"release-version\">115</span>\n          </div>\n          <div class=\"release-body\">\n            <div class=\"tag-row\"><span>Reviews</span><span>Three.js</span><span>Browser Proof</span></div>\n            <h2><span class=\"magic-highlighter\" data-highlight=\"underline\" style=\"--highlighter-color:#FF9800;display:inline;box-decoration-break:clone;-webkit-box-decoration-break:clone;text-decoration-line:underline;text-decoration-color:var(--highlighter-color);text-decoration-thickness:.16em;text-underline-offset:.13em;text-decoration-skip-ink:none\">Skyes Over London</span> Reviews shipped with a Three.js proof atlas.</h2>\n            <p>The reviews production page was re-verified with interactive review cards, detail pages, and browser proof recordings.</p>\n            <ul class=\"release-points\">\n              <li>115 clickable review cards render in production.</li>\n              <li>115 full review detail pages are available from the atlas workflow.</li>\n              <li>Three.js review atlas is active on desktop and mobile.</li>\n              <li>Client-name cleanup removed placeholder and synthetic status language from public pages.</li>\n            </ul>\n            <div class=\"receipt-row\"><span>HTTP 200</span><span>No console errors</span><span>No horizontal overflow</span><span>WebM workflow</span></div>\n          </div>\n        </article>\n\n        <article class=\"release-entry\">\n          <div class=\"release-meta\">\n            <time class=\"release-date\" datetime=\"2026-05-16\">May 16, 2026</time>\n            <span class=\"release-version\">24</span>\n          </div>\n          <div class=\"release-body\">\n            <div class=\"tag-row\"><span>Ledger</span><span>Cloudflare</span><span>Proof</span></div>\n            <h2>Production ledger captured from Cloudflare source APIs.</h2>\n            <p>The production record now summarizes Cloudflare Pages, Workers, HTTP checks, and browser proof artifacts.</p>\n            <ul class=\"release-points\">\n              <li>24 live production surfaces are recorded in the ledger.</li>\n              <li>13 Cloudflare Pages projects and 11 Workers are listed with deployment evidence.</li>\n              <li>36 HTTP routes were verified with no failures at capture time.</li>\n              <li>Proof artifacts were saved in the production evidence archive.</li>\n            </ul>\n            <div class=\"receipt-row\"><span>Cloudflare inventory</span><span>Worker inventory</span><span>HTTP checks</span><span>CEO contribution map</span></div>\n          </div>\n        </article>\n\n        <article class=\"release-entry\">\n          <div class=\"release-meta\">\n            <time class=\"release-date\" datetime=\"2026-05-15\">May 15, 2026</time>\n            <span class=\"release-version\">0S</span>\n          </div>\n          <div class=\"release-body\">\n            <div class=\"tag-row\"><span>Legacy transfer</span><span>Governance</span><span><span class=\"magic-highlighter\" data-highlight=\"highlight\" style=\"--highlighter-color:#87CEFA;display:inline;box-decoration-break:clone;-webkit-box-decoration-break:clone;border-radius:.18em;padding:0 .12em;background:linear-gradient(104deg,transparent .08em,color-mix(in srgb,var(--highlighter-color) 68%,transparent) .08em,color-mix(in srgb,var(--highlighter-color) 68%,transparent) calc(100% - .08em),transparent calc(100% - .08em));text-shadow:0 .08em .22em rgba(0,0,0,.16)\">Operator proof</span></span></div>\n            <h2>Legacy release receipt moved into the new changelog base.</h2>\n            <p>This entry transfers the old 0S release receipt so the previous public proof is still visible inside the upgraded changelog surface.</p>\n            <ul class=\"release-points\">\n              <li>Governance Center added the resolution pack, authority matrix, appointment workflow, minutes, and delegation ledger.</li>\n              <li>Pricing Center added package pages and an operator-side package fit calculator.</li>\n              <li>SEO Library added Arizona service-area pages plus index coverage.</li>\n              <li>Link Check kept internal routes verified after build.</li>\n            </ul>\n            <p class=\"legacy-note\">This replaces the older one-page release receipt as the public release record while preserving the original proof claims.</p>\n          </div>\n        </article>\n      </div>\n    </section>\n  </main>\n  <footer><p>MetrAIyux 0S changelog. Public proof is shareable; private controls stay gated.</p></footer>\n  <script src=\"../script.js\">\n";
